function v14DecodeRoute(value){try{return decodeURIComponent(value)}catch{return ''}}

/* RAWNAK ACADEMY V3 — English interactive frontend concept. No real payment, account or reward issuance. */
const $=s=>document.querySelector(s);
const icon=(id,cls='ic')=>`<svg class="${cls}" aria-hidden="true"><use href="#i-${id}"></use></svg>`;
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage={get(k,alt){try{let v=localStorage.getItem('rawnak_academy_v3_'+k);return v===null?alt:JSON.parse(v)}catch{return alt}},set(k,v){try{localStorage.setItem('rawnak_academy_v3_'+k,JSON.stringify(v))}catch{}}};
const courses=[]; const lessons=[]; const rewards=[]; const samples={weekly:[],monthly:[],season:[]}; const state={theme:storage.get('theme','atelier'),type:storage.get('type','editorial'),name:storage.get('name','Guest learner'),credits:0,xp:0,weeklyXP:0,completed:[],notes:storage.get('notes',{}),redemptions:[],quizDone:false,courseBonus:false,lesson:storage.get('lesson',0),category:'All',query:'',period:'weekly',tab:'overview',mobile:false,styleOpen:false,modal:null,selectedAnswer:null};
const persist=()=>['theme','type','name','credits','xp','weeklyXP','completed','notes','redemptions','quizDone','courseBonus','lesson'].forEach(k=>storage.set(k,state[k]));
const num=n=>Number(n).toLocaleString('en-US');
const getCourse=id=>courses.find(c=>c.id===id)||null;
const activeRoute=()=>{try{return decodeURI(location.hash.replace(/^#\/?/,''))||'welcome'}catch{return 'not-found'}};
function notify(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.classList.remove('show'),3100)}
function navigate(route){state.mobile=false;state.styleOpen=false;state.modal=null;if(activeRoute()===route){render();window.scrollTo({top:0,behavior:'instant'})}else location.hash='#/'+route}
function logo(){return `<a class="logo" href="#/home" aria-label="RAWNAK Academy home"><span class="brand-icon v76-brand-icon"><img src="assets/rawnak-academy-logo-hd.webp" width="52" height="52" alt="" decoding="async" /></span><span class="logo-text"><strong>RAWNAK</strong><small>ACADEMY</small></span></a>`}
const navItems=[['home','Discover'],['courses','Courses'],['my-learning','My Learning'],['wallet','Rewards'],['leaderboard','Leaderboard']];
function header(active){let cur=active.startsWith('course/')?'courses':active;return `<div class="announcement"><span>LEARN DIFFERENTLY</span><span class="dot"></span><span>GROW WITH INTENTION</span><span class="dot"></span><span>GET REWARDED</span></div><header class="site-header"><div class="container header-in">${logo()}<nav class="header-links" aria-label="Main navigation">${navItems.map(([r,l])=>`<button class="nav-link ${cur===r?'active':''}" data-nav="${r}">${l}</button>`).join('')}</nav><div class="header-actions"><button class="credit-pill" data-nav="wallet" aria-label="View your credits">${icon('coin')} ${num(state.credits)} CR</button><button class="btn sm outline" data-action="signin">${state.name==='Guest learner'?'Sign in':'My profile'}</button><button class="mobile-toggle" data-action="toggleMenu" aria-label="Toggle menu" aria-expanded="${state.mobile}">${icon(state.mobile?'close':'menu')}</button></div></div>${state.mobile?`<nav class="mobile-nav" aria-label="Mobile navigation">${navItems.map(([r,l])=>`<button data-nav="${r}">${l}</button>`).join('')}<button data-action="signin">Profile</button></nav>`:''}</header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-main">${logo()}<div class="footer-links"><a href="#/courses">Courses</a><a href="#/wallet">Rewards</a><a href="#/leaderboard">Community</a><a href="#/my-learning">My Learning</a><a href="https://rawnakgroup.com" target="_blank" rel="noopener">Rawnak Group ${icon('ne')}</a></div></div><div class="footer-bottom"><span>© 2026 RAWNAK ACADEMY — A RAWNAK GROUP CONCEPT</span><span>INTERACTIVE DESIGN PROTOTYPE · CONTENT, POINTS & REWARDS ARE SAMPLE DATA</span></div></div></footer>`}
function art(c){let mark={design:'<span class="symbol-main">Aa<span style="font-family:var(--font-serif);font-style:italic">.</span></span><span class="symbol-ring"></span>',development:'<span class="symbol-code">&lt;/&gt;</span><span class="symbol-ring secondary"></span>',business:'<span class="symbol-biz">↗</span>',motion:'<span class="symbol-orbit"></span>',ai:'<span class="symbol-main" style="transform:rotate(0);font-size:112px">AI.</span><span class="symbol-ring secondary"></span>',photography:'<span class="symbol-photo"></span>'}[c.art];return `<div class="course-art ${c.art}"><div class="card-art-eyebrow"><span>RAWNAK / ${escapeHtml(c.category)}</span><span class="card-art-number">${c.number}</span></div><div class="art-symbol">${mark}</div><div class="art-caption"><span>${escapeHtml(c.tag)}</span><span>${escapeHtml(c.badge)}</span></div></div>`}
function courseCard(c){return `<article class="course-card reveal" tabindex="0" role="button" data-action="course" data-id="${c.id}" aria-label="View ${escapeHtml(c.title)}">${art(c)}<div class="course-info"><div class="course-meta"><span>${escapeHtml(c.category)}</span><span>${escapeHtml(c.duration)}</span></div><h3>${escapeHtml(c.title)}</h3><p>${escapeHtml(c.sub)}</p><div class="course-bottom"><div><b>${c.count} lessons</b> <small>· ${escapeHtml(c.level)}</small></div><span class="round-icon">${icon('ne')}</span></div></div></article>`}
function courseFilter(){return `<div class="category-row">${['All','Design','Development','Business','Technology'].map(v=>`<button class="category-btn ${state.category===v?'active':''}" data-action="filter" data-category="${v}">${v==='All'?'All courses':v}</button>`).join('')}</div>`}
function hero(){return `<section class="hero"><div class="container"><div class="hero-copy appear"><div class="mini-pill">${icon('spark')} Introducing a new kind of academy</div><h1>Learn<br/>beautifully.<br/><span class="serif">Grow</span> boldly.</h1><p class="hero-desc">A considered space for curious minds. Learn practical skills, create work you are proud of, and turn every milestone into something more.</p><div class="hero-buttons"><button class="btn primary" data-nav="courses">Explore courses ${icon('ne')}</button><button class="btn outline" data-nav="classroom">${icon('play')} Experience a lesson</button></div><div class="hero-proof"><div class="hero-proof-item"><strong>06</strong><span>Curated sample paths</span></div><span class="proof-sep"></span><div class="hero-proof-item"><strong>01</strong><span>Purposeful learning space</span></div><span class="proof-sep"></span><div class="hero-proof-item"><strong>∞</strong><span>Room to grow</span></div></div></div><div class="hero-canvas appear" aria-label="Visual preview of the learning platform"><div class="canvas-dots"></div><div class="canvas-disc"></div><div class="canvas-ring"></div><div class="canvas-word">RA.</div><div class="study-card"><div class="study-top"><b>RAWNAK / YOUR STUDIO</b><div class="study-dots"><span></span><span></span><span></span></div></div><div class="study-art"><div class="study-art-top"><span>DESIGN SYSTEMS 01</span><span>CREATIVE PATH</span></div><div class="study-art-ring"></div><strong>Design for<br/><em>tomorrow.</em></strong></div><div class="study-bottom"><b>Design that feels different.</b><small>Make space for your next idea.</small><div class="progress"><span style="width:${state.completed.length/lessons.length*100||38}%"></span></div><div class="progress-caption"><span>YOUR LEARNING JOURNEY</span><strong>${state.completed.length?Math.round(state.completed.length/lessons.length*100):38}%</strong></div></div></div><div class="floating-chip one"><span class="chip-icon">${icon('zap')}</span><span><b>+25 XP</b><small>For every lesson learned</small></span></div><div class="floating-chip two"><span class="chip-icon">${icon('coin')}</span><span><b>${num(state.credits)} CR</b><small>Credits you can use</small></span></div><div class="canvas-stamp">GOOD<br/>THINGS<br/>TAKE<br/>PRACTICE</div></div></div></section>`}
function ticker(){let bits=['CREATE YOUR NEXT CHAPTER','CURIOUS MINDS WELCOME','PRACTICE MAKES PROGRESS','SKILLS THAT STAY WITH YOU'];let line=bits.map(s=>`<span>${s}</span><span class="tstar">✳</span>`).join('');return `<div class="ticker"><div class="ticker-track">${line}${line}</div></div>`}
function featuredCourses(){return `<section class="section" id="featured"><div class="container"><div class="section-head reveal"><div><div class="kicker">THE COURSE COLLECTION</div><h2>Learn something<br/><span class="serif">worth keeping.</span></h2></div><button class="btn outline" data-nav="courses">View all courses ${icon('ne')}</button></div><div class="course-grid">${courses.slice(0,3).map(courseCard).join('')}</div></div></section>`}
function momentumSection(){return `<section class="dark-section"><div class="container dark-layout"><div class="dark-copy reveal"><div class="kicker">YOUR EFFORT, RECOGNIZED</div><h2>Progress is<br/>the new <em class="serif">currency.</em></h2><p>Every completed lesson is a step forward. Earn Academy XP to track your achievements and Credits to unlock rewards. Keep learning because it matters — enjoy the extras along the way.</p><button class="btn" data-nav="wallet">Discover the rewards ${icon('ne')}</button></div><div class="dashboard-visual reveal"><div class="dash-heading"><strong>YOUR LEARNING DASHBOARD</strong><span>PERSONAL / PREVIEW</span></div><div class="dash-stats"><div class="dash-stat"><span class="small-icon">${icon('zap')}</span><strong>${num(state.xp)}</strong><small>Academy XP · never spent</small></div><div class="dash-stat"><span class="small-icon">${icon('coin')}</span><strong>${num(state.credits)}</strong><small>Credits · redeem for rewards</small></div></div><div class="dash-graph">${[26,50,38,70,61,78,100,73,88].map(v=>`<i style="height:${v}%"></i>`).join('')}</div><div style="display:flex;justify-content:space-between;gap:10px;margin-top:12px;color:color-mix(in srgb,var(--dark-text) 60%,transparent);font-size:10px"><span>LEARNING MOMENTUM</span><span>KEEP MOVING FORWARD ↗</span></div></div></div></section>`}
function benefits(){const list=[{cls:'main',icon:'gift',title:'Learn more. Get more.',desc:'Progress should feel rewarding. Unlock meaningful extras while building skills that last.'},{icon:'book',title:'A space made for focus.',desc:'A calm lesson player, thoughtful notes, and room to think.'},{icon:'trophy',title:'Move up together.',desc:'Time-based learning challenges and community leaderboards.'}];return `<section class="section"><div class="container"><div class="section-head reveal"><div><div class="kicker">MORE THAN A COURSE</div><h2>A different kind<br/>of <em class="serif">learning experience.</em></h2></div></div><div class="benefit-grid">${list.map(b=>`<div class="benefit ${b.cls||''} reveal"><span class="benefit-icon">${icon(b.icon)}</span><h3>${b.title}</h3><p>${b.desc}</p></div>`).join('')}</div></div></section>`}
function scoreboard(){return '<div class="v13-unverified-rankings">No verified rankings are available until the live learning system is connected.</div>'} function leaderboardPromo(){return `<section class="section" style="padding-top:25px"><div class="container leader-preview"><div class="reveal"><div class="kicker">COMMUNITY & CHALLENGES</div><h2>A little<br/>healthy <em class="serif" style="color:var(--brand)">ambition.</em></h2><p>Build momentum with weekly, monthly and seasonal learning challenges. Celebrate people who put learning into practice.</p><button class="btn primary" data-nav="leaderboard">Explore the leaderboard ${icon('ne')}</button></div><div class="leader-card reveal"><div class="leader-card-head"><b>THIS WEEK'S HIGHLIGHTS</b><span>DEMO STANDINGS</span></div>${scoreboard('weekly',4)}</div></div></section>`}
function cta(){return `<section class="cta-section"><div class="container reveal"><div class="kicker" style="justify-content:center">A BETTER WAY FORWARD</div><h2>Your next chapter<br/><em class="serif">starts here.</em></h2><p>Find a course that sparks your curiosity and make the first step count.</p><button class="btn dark" data-nav="courses">Find your course ${icon('ne')}</button></div></section>`}
function home(){return hero()+ticker()+featuredCourses()+momentumSection()+benefits()+leaderboardPromo()+cta()}
function coursesPage(){let selected=courses.filter(c=>(state.category==='All'||c.category===state.category)&&(`${c.title} ${c.sub} ${c.category}`.toLowerCase().includes(state.query.toLowerCase())));return `<main class="page"><div class="container"><div class="page-top"><div><div class="kicker">FIND YOUR NEXT SKILL</div><h1>The <em class="serif">collection.</em></h1><p>Explore thoughtfully created learning paths across design, technology, business and creative practice.</p></div><label class="search-box">${icon('search')}<input id="course-search" value="${escapeHtml(state.query)}" placeholder="Search courses" aria-label="Search courses" /></label></div><div id="course-filter">${courseFilter()}</div><div class="course-grid" id="course-results">${selected.length?selected.map(courseCard).join(''):'<div class="empty-state"><h3>Nothing found yet.</h3><p>Try a different search or category.</p></div>'}</div><div class="demo-note" style="margin-top:40px">All courses, lesson counts and instructors here are illustrative content for a design preview — not an active course catalogue.</div></div></main>`}
function courseDetails(id){let c=getCourse(id);return `<main class="page"><div class="container"><button class="btn plain" data-nav="courses">${icon('arrow')} Back to all courses</button><div class="course-detail"><div><div class="kicker" style="margin-top:35px">${escapeHtml(c.category)} / ${escapeHtml(c.tag)}</div><h1>${escapeHtml(c.title)}</h1><p>${escapeHtml(c.sub)} A practical, supportive learning experience with clear steps, activities and a calmer place to work.</p><div class="detail-facts"><span>${icon('clock')} ${c.duration}</span><span>${icon('book')} ${c.count} lessons</span><span>${icon('spark')} ${c.level}</span></div><button class="btn primary" data-nav="classroom">Explore the lesson player ${icon('ne')}</button><div class="curriculum"><h2>A closer look at the path</h2>${lessons.map((l,i)=>`<div class="outline-lesson"><span>${String(i+1).padStart(2,'0')}</span><b>${escapeHtml(l.title)}</b><span style="margin-left:auto;color:var(--muted)">${l.duration}</span></div>`).join('')}</div></div><aside class="detail-box">${art(c)}<div class="detail-box-content"><div class="eyebrow">COURSE PREVIEW</div><strong>Learn at your pace.</strong><p style="font-size:13px">Watch the sample lesson and explore the student experience before launch.</p><button class="btn primary" data-nav="classroom">Open lesson demo ${icon('arrow')}</button><small>Preview only. No checkout, enrollment or payment is connected.</small></div></aside></div></div></main>`}
function walletPage(){return `<main class="page"><div class="container"><div class="page-top"><div><div class="kicker">REWARDING THE WORK</div><h1>Your <em class="serif">rewards.</em></h1><p>Progress becomes possibility. Academy XP marks your achievements, while Credits can be exchanged for sample rewards.</p></div></div><div class="wallet-grid"><div class="wallet-card"><div class="eyebrow">YOUR CREDITS / DEMO WALLET</div><div class="balance">${num(state.credits)}<span class="balance-suffix"> CR</span></div><p>Earn through completed learning, redeem for benefits.</p><div style="font-size:11px;opacity:.7;margin-top:40px">RAWNAK / REWARDS PROGRAMME</div></div><div class="wallet-summary"><div class="summary-tile">${icon('zap')}<div><strong>${num(state.xp)}</strong><br/><small>Lifetime Academy XP</small></div></div><div class="summary-tile">${icon('trophy')}<div><strong>${num(state.weeklyXP)}</strong><br/><small>XP this week (demo)</small></div></div><div class="summary-tile">${icon('check')}<div><strong>${state.completed.length} / ${lessons.length}</strong><br/><small>Completed demo lessons</small></div></div><div class="summary-tile">${icon('gift')}<div><strong>${state.redemptions.length}</strong><br/><small>Demo redemptions</small></div></div></div></div><section class="section" style="padding-bottom:30px"><div class="section-head compact"><div><div class="kicker">THE REWARD COLLECTION</div><h2>Make it <em class="serif">count.</em></h2></div></div><div class="reward-grid">${rewards.map(r=>`<article class="reward-card"><span class="reward-icon">${icon(r.icon)}</span><h3>${r.name}</h3><p>${r.desc}</p><div class="reward-footer"><b>${num(r.cost)} CR</b><button class="btn sm ${state.credits>=r.cost?'primary':'outline'}" data-action="redeem" data-id="${r.id}" ${state.credits<r.cost?'disabled':''}>${state.credits>=r.cost?'Preview redeem':'Not enough CR'}</button></div></article>`).join('')}</div><div class="rewards-history"><h3>Your preview activity</h3>${state.redemptions.length?`<p>${state.redemptions.map(x=>escapeHtml(x)).join(' · ')}</p>`:'<p>No demo redemptions yet. Pick a reward to try the experience.</p>'}<p><b>Demo only:</b> credits, discounts and rewards shown here are simulated and do not create real vouchers or purchases.</p></div></section></div></main>`}
function leaderboardPage(){return `<main class="page"><div class="container"><div class="page-top"><div><div class="kicker">BETTER, TOGETHER</div><h1>The <em class="serif">leaderboard.</em></h1><p>Celebrate learning and consistent practice through time-based challenges. Only demonstrated learning achievements earn XP.</p></div></div><div class="board-grid"><section class="board-panel"><div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:13px;margin-bottom:17px"><div><div class="eyebrow">COMMUNITY RANKINGS</div><p style="color:var(--muted);font-size:11px">Illustrative names and standings</p></div><div class="period-options">${[['weekly','Weekly'],['monthly','Monthly'],['season','Season']].map(([id,label])=>`<button class="${state.period===id?'active':''}" data-action="period" data-period="${id}">${label}</button>`).join('')}</div></div><div id="leaderboard-rows">${scoreboard(state.period,9)}</div></section><aside class="board-side">${icon('trophy')}<h3>Learn for the long game.</h3><p>Challenge windows keep the competition fresh. Your XP never disappears when you spend Credits, and purchasing a course is not enough to earn a ranking.</p><p>Prizes, rules, eligibility and anti-abuse checks will be published before any real challenge begins.</p><button class="btn" data-nav="classroom">Earn XP in a lesson ${icon('ne')}</button></aside></div></div></main>`}
function tabContent(){let l=lessons[state.lesson];if(state.tab==='notes')return `<h3>Your private notes</h3><p>Write down ideas, questions and tiny breakthroughs as you go. Notes in this preview stay in this browser.</p><textarea id="lesson-notes" class="notes-input" placeholder="What stood out to you today?">${escapeHtml(state.notes[state.lesson]||'')}</textarea><p class="notes-help">Automatically saved in your browser. Do not enter sensitive information.</p>`;if(state.tab==='resources')return `<h3>Resources & practice</h3><p>Suggested practice: open your favorite design app and recreate one clear, well-spaced interface element.</p><p>${icon('check')} Write down three choices you made and why.</p><p>${icon('check')} Reflect on hierarchy, space and readability.</p><p>Course materials shown here are sample lesson content.</p>`;return `<h3>What you'll learn</h3><p>${escapeHtml(l.summary)}</p><p>${escapeHtml(l.description)}</p><p><b>A small next step:</b> take one idea from this lesson and apply it to a real project. Keep it practical, keep it yours.</p>`}
function classroomPage(){const l=lessons[state.lesson],done=state.completed.includes(state.lesson),pct=Math.round(state.completed.length/lessons.length*100);return `<main class="classroom"><div class="container"><div class="class-toolbar"><button class="back" data-nav="courses">${icon('arrow')} Back to courses</button><span class="tag">FOCUSED LEARNING MODE · DESIGN PATH / PREVIEW</span></div><div class="class-grid"><section class="class-main"><div class="video-shell"><video controls playsinline preload="metadata" poster="data:image/png;base64,"><source src="data:video/mp4;base64," type="video/mp4" />Your browser does not support the video preview.</video></div><div class="class-heading"><div class="eyebrow" style="color:#4b806b">LESSON ${String(state.lesson+1).padStart(2,'0')} / ${String(lessons.length).padStart(2,'0')}</div><h1>${escapeHtml(l.title)}</h1><p>${l.duration} · ${done?'Completed':'Ready when you are'} · RAWNAK Creative Studio</p></div><div class="class-tabs" role="tablist" aria-label="Lesson content">${[['overview','Overview'],['notes','My notes'],['resources','Resources']].map(([id,label])=>`<button role="tab" aria-selected="${state.tab===id}" class="${state.tab===id?'active':''}" data-action="tab" data-tab="${id}">${label}</button>`).join('')}</div><div class="lesson-text">${tabContent()}</div><div class="lesson-controls"><span style="font-size:12px;color:#77877e">${done?'✓ Lesson completed — progress saved locally':'Complete a lesson to earn 25 XP + 5 Credits'}</span><button class="btn primary" data-action="complete" ${done&&state.lesson===lessons.length-1?'disabled':''}>${done?'Continue learning':'Mark lesson complete'} ${icon('arrow')}</button></div><div class="demo-note">This is a functional learning UI preview. The video, lessons, XP and Credits are demo content. Course completion should be validated on a secure backend before launch.</div></section><aside class="class-side"><div class="class-side-title"><h3>Course contents</h3><span>${pct}% complete</span></div><div class="progress"><span style="width:${pct}%"></span></div><p>${state.completed.length} of ${lessons.length} demo lessons completed</p><div class="class-lesson-list">${lessons.map((li,i)=>`<button class="class-lesson ${state.lesson===i?'active':''} ${state.completed.includes(i)?'done':''}" data-action="lesson" data-index="${i}"><span class="num">${state.completed.includes(i)?icon('check'):String(i+1).padStart(2,'0')}</span><span><b>${escapeHtml(li.title)}</b><small>${li.duration}</small></span></button>`).join('')}</div>${state.completed.length===lessons.length?`<button class="btn sm" style="width:100%;margin-top:22px;background:#e2efe7;color:#285744" data-action="quiz">Take a quick knowledge check ${icon('arrow')}</button>`:`<div style="margin-top:25px;font-size:11px;color:#7b8e80">${icon('spark')} One lesson at a time. No rush.</div>`}</aside></div></div></main>`}
function styleSwitcher(){const palettes=[['atelier','Terracotta / Paper',['#f7f5f0','#c75a45','#203535']],['arctic','Arctic / Cobalt',['#f2f5f9','#2863d6','#142c4a']],['grove','Juniper / Oat',['#f3f4ec','#337d67','#1d3d34']]];return `<div class="style-switch"><button class="style-button" data-action="style" aria-expanded="${state.styleOpen}"><span class="style-swatch"></span> Design lab ${icon(state.styleOpen?'close':'spark')}</button>${state.styleOpen?`<div class="style-panel"><strong>Explore the visual direction</strong><p>Try three complete color systems and Framer-compatible font pairings.</p><span class="style-label">Colour palette</span><div class="palette-choices">${palettes.map(([id,name,colors])=>`<button class="palette-choice ${state.theme===id?'selected':''}" data-action="theme" data-theme="${id}"><span class="palette-balls">${colors.map(c=>`<i style="background:${c}"></i>`).join('')}</span><span>${name}</span></button>`).join('')}</div><label class="style-label" for="font-choice">Typography pairing</label><select id="font-choice" class="style-select" aria-label="Choose typography"><option value="editorial" ${state.type==='editorial'?'selected':''}>Inter Tight + Instrument Serif</option><option value="modern" ${state.type==='modern'?'selected':''}>Manrope + Instrument Serif</option><option value="minimal" ${state.type==='minimal'?'selected':''}>Inter + Inter Tight</option></select><p class="style-hint">Styles available in Framer's web font ecosystem. This is a coded concept, not a native Framer canvas file.</p></div>`:''}</div>`}
function modalMarkup(){if(!state.modal)return '';let wrap=(title,body)=>`<div class="modal-backdrop" data-action="modalBackdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${escapeHtml(title)}"><div class="modal-head"><h3>${escapeHtml(title)}</h3><button class="close-modal" data-action="closeModal" aria-label="Close">${icon('close')}</button></div>${body}</section></div>`;
 if(state.modal==='signin')return wrap('Preview your profile',`<p>Choose a display name for this local design demo. This is not authentication and no account is created.</p><form id="profile-form"><label class="form-label" for="profile-name">Your display name</label><input id="profile-name" class="text-field" maxlength="40" required value="${escapeHtml(state.name==='Guest learner'?'':state.name)}" placeholder="e.g. Alex Morgan"/><button type="submit" class="btn primary" style="width:100%">Save preview profile ${icon('arrow')}</button></form>`);
 if(state.modal.startsWith('redeem:')){let r=rewards.find(x=>x.id===state.modal.split(':')[1]);return wrap('Preview a redemption',`<p>Redeem <b>${escapeHtml(r.name)}</b> for <b>${r.cost} Credits</b>?</p><div class="modal-note">This changes your demo wallet only. No real voucher, review or product will be issued.</div><div style="display:flex;gap:12px;margin-top:25px"><button class="btn outline" data-action="closeModal">Cancel</button><button class="btn primary" data-action="confirmRedeem" data-id="${r.id}">Confirm preview ${icon('arrow')}</button></div>`)}
 if(state.modal==='quiz')return wrap('A quick knowledge check',`<p>Which of these best describes thoughtful interface design?</p>${[['a','Use as many effects as possible'],['b','Choose clear hierarchy and purposeful detail'],['c','Ignore the learner’s needs']].map(([v,l])=>`<button class="quiz-option ${state.selectedAnswer===v?'selected':''}" data-action="answer" data-value="${v}">${l}</button>`).join('')}<button class="btn primary" style="width:100%;margin-top:13px" data-action="submitQuiz" ${!state.selectedAnswer?'disabled':''}>Submit answer ${icon('arrow')}</button><p class="modal-note">Correct first-time completion: +60 XP and +15 Credits. Demo rewards can only be earned once.</p>`);
 return ''}
function render(){const route=activeRoute();let body=route==='home'?home():route==='courses'?coursesPage():route==='wallet'?walletPage():route==='leaderboard'?leaderboardPage():route==='my-learning'?myLearningPage():route==='classroom'?classroomPage():route.startsWith('course/')?courseDetails(route.split('/')[1]):home();document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.type=state.type;$('#app').innerHTML=header(route)+body+(route==='classroom'?'':footer())+`<div id="style-area">${styleSwitcher()}</div>`;$('#modals').innerHTML=modalMarkup();activateReveals()}
function activateReveals(){const sections=$$('.reveal');if(!('IntersectionObserver'in window)){sections.forEach(e=>e.classList.add('visible'));return}let obs=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target)}})},{threshold:.1});sections.forEach(e=>obs.observe(e))}
function $$(q){return [...document.querySelectorAll(q)]}
function setStyle(){document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.type=state.type;persist();$('#style-area').innerHTML=styleSwitcher()}
function finishLesson(){const id=state.lesson;if(!state.completed.includes(id)){state.completed.push(id);state.credits+=5;state.xp+=25;state.weeklyXP+=25;notify('Lesson complete! +25 XP and +5 Credits')}else notify('This lesson is already complete.');if(state.completed.length===lessons.length&&!state.courseBonus){state.courseBonus=true;state.credits+=70;state.xp+=200;state.weeklyXP+=200;notify('Course milestone! +200 XP and +70 Credits')}if(id<lessons.length-1)state.lesson=id+1;persist();render()}
function handleAction(target){let action=target.dataset.action,route=target.dataset.nav;if(route){navigate(route);return}if(!action)return;
 if(action==='toggleMenu'){state.mobile=!state.mobile;render();return}if(action==='signin'){state.modal='signin';renderModal();return}if(action==='closeModal'){state.modal=null;renderModal();return}if(action==='modalBackdrop'){if(target.classList.contains('modal-backdrop')){state.modal=null;renderModal()}return}if(action==='course'){navigate('course/'+target.dataset.id);return}if(action==='filter'){state.category=target.dataset.category;render();return}if(action==='period'){state.period=target.dataset.period;render();return}if(action==='style'){state.styleOpen=!state.styleOpen;$('#style-area').innerHTML=styleSwitcher();return}if(action==='theme'){state.theme=target.dataset.theme;setStyle();return}if(action==='lesson'){state.lesson=Number(target.dataset.index);state.tab='overview';persist();render();return}if(action==='tab'){state.tab=target.dataset.tab;render();return}if(action==='complete'){finishLesson();return}if(action==='redeem'){state.modal='redeem:'+target.dataset.id;renderModal();return}if(action==='confirmRedeem'){let r=rewards.find(x=>x.id===target.dataset.id);if(r&&state.credits>=r.cost){state.credits-=r.cost;state.redemptions.push(r.name+' (-'+r.cost+' CR)');persist();state.modal=null;render();notify('Demo reward redeemed. No real purchase was made.')}return}if(action==='quiz'){state.modal='quiz';state.selectedAnswer=null;renderModal();return}if(action==='answer'){state.selectedAnswer=target.dataset.value;renderModal();return}if(action==='submitQuiz'){if(state.selectedAnswer!=='b'){notify('Not quite. Think about clarity and purpose.');return}if(!state.quizDone){state.quizDone=true;state.xp+=60;state.weeklyXP+=60;state.credits+=15;persist();notify('Correct! +60 XP and +15 Credits')}else notify('Correct! You already earned the quiz reward.');state.modal=null;render();return}}
function renderModal(){$('#modals').innerHTML=modalMarkup();let inp=$('#profile-name');if(inp&&state.modal==='signin')inp.focus()}
document.addEventListener('click',e=>{let t=e.target.closest('[data-nav],[data-action]');if(t && (t.dataset.action!=='modalBackdrop' || t===e.target))handleAction(t)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;renderModal()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('.course-card[role="button"]')){e.preventDefault();navigate('course/'+e.target.dataset.id)}});
document.addEventListener('input',e=>{if(e.target.id==='lesson-notes'){state.notes[state.lesson]=e.target.value;persist()}if(e.target.id==='course-search'){state.query=e.target.value;let list=courses.filter(c=>(state.category==='All'||state.category===c.category)&&(`${c.title} ${c.sub} ${c.category}`.toLowerCase().includes(state.query.toLowerCase())));$('#course-results').innerHTML=list.length?list.map(courseCard).join(''):'<div class="empty-state"><h3>Nothing found yet.</h3><p>Try a different search or category.</p></div>';activateReveals()}});
document.addEventListener('change',e=>{if(e.target.id==='font-choice'){state.type=e.target.value;setStyle()}});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();let name=$('#profile-name').value.trim();if(name){state.name=name;persist();state.modal=null;render();notify('Preview profile updated')}}});
window.addEventListener('hashchange',()=>{state.mobile=false;state.styleOpen=false;state.modal=null;render();window.scrollTo({top:0,behavior:'instant'})});

/* RAWNAK Academy V4 / Theme Studio & Motion Lab extension. Preserves all V3 course logic. */
const v4Palettes=[
 {id:'atelier',label:'Atelier',desc:'Terracotta',colors:['#f7f5f0','#c75a45','#203535']},
 {id:'arctic',label:'Arctic',desc:'Cobalt',colors:['#f2f5f9','#2863d6','#142c4a']},
 {id:'grove',label:'Grove',desc:'Juniper',colors:['#f3f4ec','#337d67','#1d3d34']},
 {id:'mist',label:'Tide',desc:'Sea glass',colors:['#eff7f5','#168c7b','#173e3b']},
 {id:'blush',label:'Bloom',desc:'Rose quartz',colors:['#fcf4f2','#b65581','#322b3b']},
 {id:'solar',label:'Solstice',desc:'Warm apricot',colors:['#fcf8ed','#cf792f','#403527']},
 {id:'custom',label:'My palette',desc:'Your own colors',colors:['#f6f5f0','#2e7b88','#25363f']}
];
state.v4Custom=storage.get('v4Custom',{background:'#f6f5f0',accent:'#2e7b88',ink:'#25363f'});
state.v4Motion=storage.get('v4Motion','expressive');
state.v4Tilt=storage.get('v4Tilt',true);
state.v4Ambient=storage.get('v4Ambient',true);
state.v4SettingsOpen=state.styleOpen;
const v4PrefersReduced=window.matchMedia('(prefers-reduced-motion: reduce)');
function v4Persist(){storage.set('v4Custom',state.v4Custom);storage.set('v4Motion',state.v4Motion);storage.set('v4Tilt',state.v4Tilt);storage.set('v4Ambient',state.v4Ambient);persist()}
function v4Rgb(color){return [1,3,5].map(i=>parseInt(color.slice(i,i+2),16))}
function v4Hex(c){return '#'+c.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('')}
function v4Mix(a,b,n){const aa=v4Rgb(a),bb=v4Rgb(b);return v4Hex(aa.map((v,i)=>v*(1-n)+bb[i]*n))}
function v4PaletteColor(id){const v=state.v4Custom;return id==='custom'?[v.background,v.accent,v.ink]:(v4Palettes.find(x=>x.id===id)||v4Palettes[0]).colors}
function v4Apply(){
 const root=document.documentElement;
 root.dataset.motion=state.v4Motion;
 const customKeys=['--bg','--paper','--surface','--ink','--muted','--stroke','--brand','--brand-ink','--brand-pale','--dark','--dark-text','--hero-tint','--art-a','--art-b','--art-c','--glass'];
 customKeys.forEach(k=>root.style.removeProperty(k));
 if(state.theme==='custom'){
 const {background:b,accent:a,ink:i}=state.v4Custom;
 const white='#ffffff';const luminance=v4Rgb(a).map((v,j)=>v/255*[.2126,.7152,.0722][j]).reduce((x,y)=>x+y,0);
 const values={'--bg':b,'--paper':v4Mix(b,white,.67),'--surface':white,'--ink':i,'--muted':v4Mix(i,b,.52),'--stroke':v4Mix(i,b,.86),'--brand':a,'--brand-ink':luminance>.66?'#1c2425':'#ffffff','--brand-pale':v4Mix(a,b,.85),'--dark':v4Mix(i,a,.17),'--dark-text':'#f9ffff','--hero-tint':v4Mix(a,b,.89),'--art-a':v4Mix(a,b,.72),'--art-b':v4Mix(i,b,.81),'--art-c':a,'--glass':'rgba(255,255,255,.88)'};
 for(let [k,v] of Object.entries(values))root.style.setProperty(k,v)
 }
 const focus=activeRoute()==='classroom';
 document.body.classList.toggle('v4-focus',focus);
 const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',v4PaletteColor(state.theme)[0]);
}
function v4Choice(p){const c=p.id==='custom'?v4PaletteColor('custom'):p.colors;return `<button type="button" class="palette-choice ${state.theme===p.id?'selected':''}" data-action="v4theme" data-theme="${p.id}" aria-pressed="${state.theme===p.id}"><span class="palette-balls">${c.map(x=>`<i style="background:${x}"></i>`).join('')}</span><span>${p.label} <small style="font-weight:500;color:var(--muted)">/ ${p.desc}</small></span></button>`}
styleSwitcher=function(){return `<div class="style-switch"><button class="style-button" data-action="style" aria-expanded="${state.styleOpen}" aria-label="${state.styleOpen?'Close':'Open'} Theme Studio"><span class="style-swatch"></span> Theme Studio ${icon(state.styleOpen?'close':'spark')}</button>${state.styleOpen?`<div class="style-panel" role="region" aria-label="Theme and motion customization"><div class="studio-intro">${icon('spark')} LIVE PERSONALIZATION</div><div class="style-panel-head"><h3>Make it yours.</h3><span class="atlas-badge">SAVED</span></div><p class="studio-sub">Design your learning universe. Your look is saved in this browser — lessons always stay calm.</p><div class="style-label">01 / CURATED PALETTES</div><div class="palette-choices">${v4Palettes.map(v4Choice).join('')}</div><div class="style-label">02 / CREATE YOUR PALETTE</div><div class="theme-color-row"><label>Background<input type="color" data-v4color="background" value="${state.v4Custom.background}" aria-label="Custom background"/></label><label>Accent<input type="color" data-v4color="accent" value="${state.v4Custom.accent}" aria-label="Custom accent"/></label><label>Text<input type="color" data-v4color="ink" value="${state.v4Custom.ink}" aria-label="Custom text"/></label></div><label class="style-label" for="font-choice">03 / FRAMER FONT PAIRINGS</label><select id="font-choice" class="style-select"><option value="editorial" ${state.type==='editorial'?'selected':''}>Inter Tight / DM Sans / Instrument Serif</option><option value="modern" ${state.type==='modern'?'selected':''}>Manrope / Instrument Serif</option><option value="minimal" ${state.type==='minimal'?'selected':''}>Inter / Inter Tight</option><option value="kinetic" ${state.type==='kinetic'?'selected':''}>Space Grotesk / DM Sans</option><option value="sora" ${state.type==='sora'?'selected':''}>Sora / DM Sans</option></select><div class="style-label">04 / MOTION PERSONALITY</div><div class="studio-segment">${[['subtle','Subtle'],['expressive','Dynamic'],['off','Off']].map(([id,label])=>`<button data-action="v4motion" data-motion="${id}" class="${state.v4Motion===id?'active':''}" aria-pressed="${state.v4Motion===id}">${label}</button>`).join('')}</div><label class="studio-toggle">Interactive 3D cards<input type="checkbox" id="v4-tilt" ${state.v4Tilt?'checked':''}/></label><label class="studio-toggle">Ambient moving details<input type="checkbox" id="v4-ambient" ${state.v4Ambient?'checked':''}/></label><div class="studio-save"><span>Preferences saved locally · Demo</span><button data-action="v4reset">Restore defaults</button></div>${v4PrefersReduced.matches?'<p style="font-size:11px;color:var(--muted)">System accessibility settings have reduced motion enabled.</p>':''}</div>`:''}</div>`}
function v4Atlas(){let percent=Math.round(state.completed.length/lessons.length*100);return `<section class="v4-feature" aria-label="Interactive skill atlas"><div class="container"><div class="v4-feature-head reveal"><div><div class="kicker">THE LEARNING UNIVERSE</div><h2>Your next skill<br/><em class="serif" style="color:var(--brand)">is out there.</em></h2></div><p>Explore connected paths, collect real progress, and make every new skill part of something bigger.</p></div><div class="atlas-layout"><div class="atlas-world reveal" data-v4-spotlight><div class="atlas-grid"></div><div class="atlas-center"><strong>RA<span style="color:var(--brand)">.</span></strong><small>SKILL ATLAS</small></div><button class="atlas-node n1" data-nav="course/design"><span class="dot"></span>Design Systems ↗</button><button class="atlas-node n2" data-nav="course/development"><span class="dot"></span>Development ↗</button><button class="atlas-node n3" data-nav="course/business"><span class="dot"></span>Entrepreneurship ↗</button><button class="atlas-node n4" data-nav="course/ai"><span class="dot"></span>AI & Innovation ↗</button><div class="atlas-caption"><span>EXPLORE THE UNIVERSE</span><span>04 / FEATURED PATHS</span></div></div><div class="atlas-side reveal"><div><div class="atlas-side-top"><span class="atlas-badge">✦ YOUR UNIVERSE</span><span class="eyebrow muted">LIVE DEMO</span></div><h3>Build a journey<br/><em class="serif">worth celebrating.</em></h3><p>Your progress is personal. Your XP reflects achievements; Credits unlock extra value.</p><div class="atlas-progress" style="--progress:${percent}%"><span></span></div><div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted)"><span>Course journey</span><strong>${percent}% complete</strong></div><div class="atlas-metrics"><div class="atlas-metric"><b>${num(state.xp)}</b><small>Total Academy XP</small></div><div class="atlas-metric"><b>${num(state.credits)}</b><small>Spendable Credits</small></div></div></div><button class="btn primary" data-nav="classroom">Continue learning ${icon('ne')}</button></div></div></div></section>`}
const v4OldHome=home;home=function(){const s=v4OldHome();return s.replace('<section class="cta-section">',v4Atlas()+'<section class="cta-section">')};
const v4OldHero=hero;hero=function(){return v4OldHero().replace('<section class="hero">','<section class="hero"><canvas class="academy-ambient" id="v4-ambient" aria-hidden="true"></canvas>')};
const v4OldCard=courseCard;courseCard=function(c){return v4OldCard(c).replace('class="course-card reveal"','class="course-card reveal" data-v4-tilt data-v4-spotlight')};
const v4OldMomentum=momentumSection;momentumSection=function(){return v4OldMomentum().replace('class="dashboard-visual reveal"','class="dashboard-visual reveal" data-v4-spotlight')};
function v4Mount(){v4Apply();if(!$('#v4-scroll-track')){let p=document.createElement('div');p.id='v4-scroll-track';p.setAttribute('aria-hidden','true');document.body.appendChild(p)}v4Scroll();v4AmbientStart();}
const v4OldRender=render;render=function(){v4AmbientStop();v4OldRender();v4Mount()};
function v4Scroll(){const b=$('#v4-scroll-track');if(!b)return;const doc=document.documentElement;const max=doc.scrollHeight-window.innerHeight;b.style.width=(max>0?Math.min(100,Math.max(0,window.scrollY/max*100)):0)+'%'}
let v4Raf=0,v4Canvas=null,v4CanvasCtx=null,v4Dots=[];
function v4AmbientStop(){if(v4Raf)cancelAnimationFrame(v4Raf);v4Raf=0;v4Canvas=null;v4CanvasCtx=null}
function v4AmbientStart(){if(activeRoute()==='classroom'||state.v4Motion==='off'||!state.v4Ambient||v4PrefersReduced.matches)return;v4Canvas=$('#v4-ambient');if(!v4Canvas||typeof v4Canvas.getContext!=='function'){v4Canvas=null;return}v4CanvasCtx=v4Canvas.getContext('2d');if(!v4CanvasCtx)return;let frame=v4Canvas.getBoundingClientRect();const ratio=Math.min(devicePixelRatio||1,2);v4Canvas.width=Math.max(1,Math.floor(frame.width*ratio));v4Canvas.height=Math.max(1,Math.floor(frame.height*ratio));v4CanvasCtx.setTransform(ratio,0,0,ratio,0,0);const n=window.innerWidth<700?13:27;v4Dots=Array.from({length:n},(_,i)=>({x:(i*139.1+40)%frame.width,y:(i*77.9+30)%frame.height,r:(i%4+1)*.45,s:(i%3+1)*.09,angle:i*2.2}));let t=0;function draw(){if(!v4CanvasCtx||!v4Canvas)return;const ctx=v4CanvasCtx;ctx.clearRect(0,0,frame.width,frame.height);ctx.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--brand').trim()||'#168c7b';for(const p of v4Dots){ctx.globalAlpha=.11;ctx.beginPath();ctx.arc(p.x+Math.cos(t*.3+p.angle)*8,p.y+Math.sin(t*.3+p.angle)*8,p.r,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;t+=state.v4Motion==='subtle'?.008:.018;v4Raf=requestAnimationFrame(draw)}draw()}
window.addEventListener('resize',()=>{v4Scroll();if(v4Canvas){v4AmbientStop();v4AmbientStart()}},{passive:true});window.addEventListener('scroll',v4Scroll,{passive:true});
document.addEventListener('pointermove',e=>{if(state.v4Motion==='off'||v4PrefersReduced.matches||activeRoute()==='classroom')return;const c=e.target.closest('[data-v4-tilt],[data-v4-spotlight]');if(!c)return;const r=c.getBoundingClientRect();const xp=(e.clientX-r.left)/r.width,yp=(e.clientY-r.top)/r.height;c.style.setProperty('--glowX',(xp*100).toFixed(1)+'%');c.style.setProperty('--glowY',(yp*100).toFixed(1)+'%');if(state.v4Tilt&&c.hasAttribute('data-v4-tilt')&&e.pointerType!=='touch'){const intensity=c.classList.contains('hero-canvas')?2.3:4;c.style.setProperty('--tiltX',((.5-yp)*intensity).toFixed(2)+'deg');c.style.setProperty('--tiltY',((xp-.5)*intensity).toFixed(2)+'deg')}});
document.addEventListener('pointerout',e=>{const c=e.target.closest('[data-v4-tilt]');if(c&&!c.contains(e.relatedTarget)){c.style.setProperty('--tiltX','0deg');c.style.setProperty('--tiltY','0deg')}});
const v4OldHandle=handleAction;handleAction=function(t){const a=t.dataset.action;if(a==='v4theme'){const apply=()=>{state.theme=t.dataset.theme;v4Persist();setStyle()};if(document.startViewTransition && state.v4Motion!=='off'&&!v4PrefersReduced.matches)document.startViewTransition(apply);else apply();return}if(a==='v4motion'){state.v4Motion=t.dataset.motion;v4Persist();v4AmbientStop();setStyle();v4AmbientStart();return}if(a==='v4reset'){state.theme='atelier';state.type='editorial';state.v4Custom={background:'#f6f5f0',accent:'#2e7b88',ink:'#25363f'};state.v4Motion='expressive';state.v4Tilt=true;state.v4Ambient=true;v4Persist();setStyle();v4AmbientStop();v4AmbientStart();notify('Your design studio has been reset.');return}return v4OldHandle(t)};
const v4OldSetStyle=setStyle;setStyle=function(){v4OldSetStyle();v4Apply()};
document.addEventListener('input',e=>{const field=e.target.dataset.v4color;if(!field)return;state.v4Custom[field]=e.target.value;state.theme='custom';v4Persist();document.documentElement.dataset.theme='custom';v4Apply();const options=document.querySelectorAll('.palette-choice');options.forEach(x=>x.classList.toggle('selected',x.dataset.theme==='custom'))});
document.addEventListener('change',e=>{if(e.target.dataset.v4color){setStyle();return}if(e.target.id==='v4-tilt'){state.v4Tilt=e.target.checked;v4Persist()}if(e.target.id==='v4-ambient'){state.v4Ambient=e.target.checked;v4Persist();v4AmbientStop();v4AmbientStart()}});
const v4OldFinish=finishLesson;finishLesson=function(){const prev=state.completed.length;v4OldFinish();if(state.completed.length>prev&&state.v4Motion!=='off'&&!v4PrefersReduced.matches)v4Celebrate()};
function v4Celebrate(){const old=document.querySelector('.v4-burst');old?.remove();const box=document.createElement('div');box.className='v4-burst';const colors=[getComputedStyle(document.documentElement).getPropertyValue('--brand').trim(),'#f0bb69','#91dcca','#d9acd9'];box.innerHTML=Array.from({length:32},(_,i)=>`<i class="v4-confetti" style="--x:${(i*53.71)%100}%;--c:${colors[i%colors.length]};--r:${(i*97)%360}deg;--dx:${(i%2?-1:1)*(40+i*5)}px;--spin:${i*42}deg;--d:${1.6+(i%6)*.2}s"></i>`).join('');document.body.append(box);setTimeout(()=>box.remove(),2900)}
v4PrefersReduced.addEventListener?.('change',()=>{v4AmbientStop();v4AmbientStart()});

/* V4.1 3D course carousel / lightweight command search */
let v4CarouselIndex=0;
function v4Showcase(){return `<section class="v4-showcase"><div class="container"><div class="v4-showcase-top reveal"><div class="kicker">INTERACTIVE COURSE GALLERY</div><h2>A new perspective<br/><em class="serif" style="color:var(--brand)">on what's possible.</em></h2><p>Explore the next chapter in 3D. Drag or use the arrows to find a path that feels like yours.</p></div><div class="v4-slide-stage" role="region" aria-label="Interactive 3D course carousel" tabindex="0">${courses.slice(0,5).map((c,i)=>`<button class="v4-slide" data-action="v4slideOpen" data-index="${i}" aria-label="Explore ${escapeHtml(c.title)}"><div class="v4-slide-top"><span class="v4-slide-id">COURSE / ${c.number}</span><span class="v4-slide-icon">✳</span></div><div class="v4-slide-art"></div><div class="v4-slide-body"><h3>${escapeHtml(c.title)}</h3><p>${escapeHtml(c.sub)}</p></div></button>`).join('')}</div><div class="v4-carousel-controls"><button data-action="v4slideShift" data-dir="-1" aria-label="Previous course">←</button><span class="v4-carousel-count" id="v4-slide-count">01 / 05</span><button data-action="v4slideShift" data-dir="1" aria-label="Next course">→</button></div></div></section>`}
const v4OldHome2=home;home=function(){return v4OldHome2().replace('<section class="cta-section">',v4Showcase()+'<section class="cta-section">')};
const v4OldHeader=header;header=function(route){return v4OldHeader(route).replace('<div class="header-actions">','<div class="header-actions"><button class="v4-command-btn" data-action="v4command" aria-label="Search the academy">⌕ <span>Search</span> <small>⌘ K</small></button>')};
function v4UpdateCarousel(){const cards=$$('.v4-slide');if(!cards.length)return;const n=cards.length;cards.forEach((el,i)=>{const offset=(i-v4CarouselIndex+n)%n;el.classList.toggle('is-active',offset===0);el.classList.toggle('is-left',offset===n-1);el.classList.toggle('is-right',offset===1);el.setAttribute('aria-hidden',offset>1&&offset<n-1?'true':'false');el.tabIndex=offset===0?0:-1});const count=$('#v4-slide-count');if(count)count.textContent=String(v4CarouselIndex+1).padStart(2,'0')+' / '+String(n).padStart(2,'0')}
function v4ShiftCarousel(delta){v4CarouselIndex=(v4CarouselIndex+delta+5)%5;v4UpdateCarousel()}
const v4OldRender2=render;render=function(){v4OldRender2();v4UpdateCarousel()};
const v4OldHandle2=handleAction;handleAction=function(t){const a=t.dataset.action;if(a==='v4slideShift'){v4ShiftCarousel(Number(t.dataset.dir));return}if(a==='v4slideOpen'){const index=Number(t.dataset.index);if(index===v4CarouselIndex)navigate('course/'+courses[index].id);else{v4CarouselIndex=index;v4UpdateCarousel()}return}if(a==='v4command'){v4OpenCommand();return}if(a==='v4go'){const route=t.dataset.route;v4CloseCommand();navigate(route);return}if(a==='v4close'){v4CloseCommand();return}return v4OldHandle2(t)};
function v4OpenCommand(){if($('#v4-cmd-bg'))return;const d=document.createElement('div');d.className='v4-command-bg';d.id='v4-cmd-bg';d.innerHTML=`<div class="v4-command" role="dialog" aria-modal="true" aria-label="Search academy"><div class="v4-command-head"><span style="font-size:23px">⌕</span><input id="v4-cmd-input" placeholder="Search courses, pages, rewards..." aria-label="Search academy" autocomplete="off"/><button class="v4-command-close" data-action="v4close">ESC</button></div><div class="v4-command-list" id="v4-cmd-results"></div><div class="v4-command-hint">Keyboard shortcut Ctrl / ⌘ + K · Escape to close</div></div>`;document.body.appendChild(d);v4FilterCommand('');$('#v4-cmd-input')?.focus()}
function v4CloseCommand(){document.querySelector('#v4-cmd-bg')?.remove()}
function v4FilterCommand(q){const list=$('#v4-cmd-results');if(!list)return;const pages=[{title:'Discover',route:'home',group:'PAGE'},{title:'All courses',route:'courses',group:'PAGE'},{title:'My Learning dashboard',route:'my-learning',group:'PAGE'},{title:'Classroom',route:'classroom',group:'PAGE'},{title:'Rewards & Credits',route:'wallet',group:'PAGE'},{title:'Leaderboard',route:'leaderboard',group:'PAGE'}];const items=[...pages,...courses.map(c=>({title:c.title,route:'course/'+c.id,group:c.category}))].filter(x=>x.title.toLowerCase().includes(q.toLowerCase())||x.group.toLowerCase().includes(q.toLowerCase())).slice(0,9);list.innerHTML=items.map(x=>`<button data-action="v4go" data-route="${x.route}">${escapeHtml(x.title)} <span>${escapeHtml(x.group)} ↗</span></button>`).join('')||'<p style="padding:10px;color:var(--muted)">No results found.</p>'}
document.addEventListener('input',e=>{if(e.target.id==='v4-cmd-input')v4FilterCommand(e.target.value)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();v4OpenCommand()}if(e.key==='Escape'){v4CloseCommand()}if(e.target.classList?.contains('v4-slide-stage')){if(e.key==='ArrowRight'){e.preventDefault();v4ShiftCarousel(1)}if(e.key==='ArrowLeft'){e.preventDefault();v4ShiftCarousel(-1)}}});
document.addEventListener('click',e=>{if(e.target.id==='v4-cmd-bg')v4CloseCommand()});
let v4DragStart=null;
document.addEventListener('pointerdown',e=>{if(e.target.closest('.v4-slide-stage'))v4DragStart=e.clientX});
document.addEventListener('pointerup',e=>{if(v4DragStart===null)return;let distance=e.clientX-v4DragStart;v4DragStart=null;if(Math.abs(distance)>54){v4ShiftCarousel(distance>0?-1:1)}});



/* V5: selected curated themes + opt-in Advanced + Light/Dark/System. V4 visual structure preserved. */
state.v5Mode=storage.get('v5Mode','system');
if(!['light','dark','system'].includes(state.v5Mode))state.v5Mode='system';
state.v5Advanced=storage.get('v5Advanced',false);
state.v5CustomDark=storage.get('v5CustomDark',{background:'#151e24',accent:'#80c5d4',ink:'#f0f7fa'});
