state.v5Positions=storage.get('v5Positions',{});
const v5SystemDark=window.matchMedia('(prefers-color-scheme: dark)');
const v5DarkPalettes={
 atelier:{bg:'#171d1e',paper:'#202a29',surface:'#25302e',ink:'#f6f4ed',muted:'#b8c9c2',stroke:'#455651',brand:'#e79a83',brandInk:'#192120',dark:'#111d1d',darkText:'#f7f4ef',hero:'#25312d',a:'#a76e5c',b:'#3d6158'},
 arctic:{bg:'#0d182a',paper:'#14243a',surface:'#1a2b42',ink:'#f1f6ff',muted:'#b5c6df',stroke:'#384e69',brand:'#95beff',brandInk:'#101e32',dark:'#0a1324',darkText:'#f1f6ff',hero:'#1a304c',a:'#4d79bc',b:'#2a6880'},
 grove:{bg:'#121f19',paper:'#192a22',surface:'#20372b',ink:'#f0f6ee',muted:'#b0c8b7',stroke:'#395747',brand:'#96ddb4',brandInk:'#11231a',dark:'#102016',darkText:'#f1f7f0',hero:'#243c2e',a:'#6b9c7b',b:'#687b55'},
 mist:{bg:'#0d2022',paper:'#143034',surface:'#1b3b3e',ink:'#f0fbfa',muted:'#b0d0d0',stroke:'#416267',brand:'#7de1cf',brandInk:'#102d2a',dark:'#0c1d22',darkText:'#f5fffd',hero:'#204247',a:'#5b9995',b:'#496d86'},
 blush:{bg:'#241b26',paper:'#302431',surface:'#392c3b',ink:'#fff2fa',muted:'#d9bfcf',stroke:'#694d65',brand:'#f3b2d2',brandInk:'#311e2b',dark:'#1b1722',darkText:'#fff4fb',hero:'#3a293a',a:'#b1789a',b:'#775e90'},
 solar:{bg:'#211c17',paper:'#302720',surface:'#3a2f25',ink:'#fff6e8',muted:'#dbc9b4',stroke:'#655445',brand:'#f0bc7e',brandInk:'#332012',dark:'#211a15',darkText:'#fff8ed',hero:'#3f3325',a:'#bc8a5c',b:'#8d7e58'}
};
const v5Resolved=()=>state.v5Mode==='system'?(v5SystemDark.matches?'dark':'light'):state.v5Mode;
const v5Persist=()=>{for(const k of ['v5Mode','v5Advanced','v5CustomDark','v5Focus','v5Speed','v5Pins','v5Positions'])storage.set(k,state[k]);v4Persist()};
function v5Luminance(hex){const rgb=v4Rgb(hex).map(n=>{n/=255;return n<=.04045?n/12.92:((n+.055)/1.055)**2.4});return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722}
function v5Contrast(a,b){const x=v5Luminance(a),y=v5Luminance(b);return ((Math.max(x,y)+.05)/(Math.min(x,y)+.05))}
const v5FormatTime=(secs)=>`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(Math.floor(secs%60)).padStart(2,'0')}`;
function v5Colors(mode){if(state.theme==='custom'){const v=mode==='dark'?state.v5CustomDark:state.v4Custom;return [v.background,v.accent,v.ink]}
 const p=(v4Palettes.find(p=>p.id===state.theme)||v4Palettes[0]);if(mode==='light')return p.colors;
 const dark=v5DarkPalettes[state.theme]||v5DarkPalettes.atelier;return [dark.bg,dark.brand,dark.ink];}
const v5OldApply=v4Apply;
v4Apply=function(){v5OldApply();const root=document.documentElement;const mode=v5Resolved();root.dataset.appearance=mode;root.dataset.appearancePreference=state.v5Mode;
 if(mode==='dark'){
  const p=state.theme==='custom'?(()=>{let v=state.v5CustomDark,b=v.background,a=v.accent,i=v.ink;return {bg:b,paper:v4Mix(b,'#ffffff',.055),surface:v4Mix(b,'#ffffff',.10),ink:i,muted:v4Mix(i,b,.33),stroke:v4Mix(i,b,.73),brand:a,brandInk:v5Contrast(a,'#162220')>=4.5?'#162220':'#ffffff',dark:v4Mix(b,'#000000',.18),darkText:i,hero:v4Mix(b,a,.12),a:v4Mix(b,a,.5),b:v4Mix(b,i,.22)}})():v5DarkPalettes[state.theme]||v5DarkPalettes.atelier;
  const values={'--bg':p.bg,'--paper':p.paper,'--surface':p.surface,'--ink':p.ink,'--muted':p.muted,'--stroke':p.stroke,'--brand':p.brand,'--brand-ink':p.brandInk,'--brand-pale':v4Mix(p.bg,p.brand,.14),'--dark':p.dark,'--dark-text':p.darkText,'--hero-tint':p.hero,'--art-a':p.a,'--art-b':p.b,'--art-c':p.brand,'--glass':'rgba(20,26,29,.88)'};
  for(const [key,value] of Object.entries(values))root.style.setProperty(key,value);
 }else if(state.theme==='custom'){
  const c=state.v4Custom;root.style.setProperty('--muted',v4Mix(c.ink,c.background,.48));
  root.style.setProperty('--brand-ink',v5Contrast(c.accent,'#171d1f')>v5Contrast(c.accent,'#ffffff')?'#171d1f':'#ffffff');
 }
 const meta=$('meta[name="theme-color"]');if(meta)meta.setAttribute('content',getComputedStyle(root).getPropertyValue('--bg').trim()||v5Colors(mode)[0]);
};
function v5SwatchFor(p,mode){if(p.id==='custom'){const v=mode==='dark'?state.v5CustomDark:state.v4Custom;return [v.background,v.accent,v.ink]}
 return mode==='dark'?[v5DarkPalettes[p.id].bg,v5DarkPalettes[p.id].brand,v5DarkPalettes[p.id].ink]:p.colors}
function v5ContrastHint(){const v=v5Resolved()==='dark'?state.v5CustomDark:state.v4Custom;const ratio=v5Contrast(v.background,v.ink);const accentRatio=v5Contrast(v.background,v.accent);return `<div class="v5-contrast ${ratio>=4.5?'pass':'fail'}" aria-live="polite"><strong>${ratio>=4.5?'✓ Readable text':'⚠ Low text contrast'}</strong> · ${ratio.toFixed(2)}:1 against background. ${ratio<4.5?'Use stronger text contrast.':''}<div>Accent visibility ${accentRatio.toFixed(2)}:1 · WCAG text target: 4.5:1.</div>${ratio<4.5?'<button type="button" class="btn sm outline" data-action="v5FixContrast">Improve text contrast</button>':''}</div>`}
styleSwitcher=function(){const mode=v5Resolved();const custom=mode==='dark'?state.v5CustomDark:state.v4Custom;return `<div class="style-switch"><button class="style-button" data-action="style" aria-expanded="${state.styleOpen}" aria-controls="v5-style-panel" aria-label="Open Theme Studio"><span class="style-swatch"></span> Theme Studio ${icon(state.styleOpen?'close':'spark')}</button>${state.styleOpen?`<div id="v5-style-panel" class="style-panel v5-studio" role="region" aria-label="Theme Studio"><div class="studio-intro">✦ YOUR CREATIVE SPACE · V5</div><div class="style-panel-head"><h3>Made for you.</h3><span class="atlas-badge">LOCAL DEMO</span></div><p class="studio-sub">Curated looks. One beautiful learning space. Your preference stays in this browser.</p><div class="style-label">01 / APPEARANCE</div><div class="v5-mode-grid" role="group" aria-label="Color appearance">${[['light','☼','Light'],['dark','☾','Dark'],['system','◐','System']].map(([id,ic,label])=>`<button data-action="v5mode" data-mode="${id}" class="${state.v5Mode===id?'active':''}" aria-pressed="${state.v5Mode===id}">${ic} ${label}</button>`).join('')}</div><div class="style-label">02 / CURATED THEMES</div><div class="v5-palette-grid">${v4Palettes.filter(p=>p.id!=='custom').map(p=>`<button style="background:${v5SwatchFor(p,mode)[0]};color:${v5SwatchFor(p,mode)[2]};border-color:${v5SwatchFor(p,mode)[1]}55" class="palette-choice ${state.theme===p.id?'selected':''}" data-action="v4theme" data-theme="${p.id}" aria-pressed="${state.theme===p.id}"><span class="palette-balls">${v5SwatchFor(p,mode).map(c=>`<i style="background:${c}"></i>`).join('')}</span><span style="color:${v5SwatchFor(p,mode)[2]}">${p.label}<small style="color:${v5SwatchFor(p,mode)[2]};opacity:.78">${p.desc}</small></span></button>`).join('')}</div><details id="v5-advanced" ${state.v5Advanced?'open':''}><summary>Advanced personalization <small>Optional</small></summary><p class="studio-sub">Your custom palette is separate for Light and Dark.</p><button class="btn sm outline" data-action="v5custom" style="width:100%">${state.theme==='custom'?'✓ Using my palette':'Activate my custom palette'}</button><div class="style-label">CUSTOM ${mode.toUpperCase()} COLORS</div><div class="theme-color-row"><label>Background<input type="color" data-v5color="background" value="${custom.background}" aria-label="${mode} background"></label><label>Accent<input type="color" data-v5color="accent" value="${custom.accent}" aria-label="${mode} accent"></label><label>Text<input type="color" data-v5color="ink" value="${custom.ink}" aria-label="${mode} text"></label></div>${v5ContrastHint()}<label class="style-label" for="font-choice">FRAMER FONT PAIRINGS</label><select id="font-choice" class="style-select">${[['editorial','Inter Tight · DM Sans · Instrument Serif'],['modern','Manrope · Instrument Serif'],['minimal','Inter · Inter Tight'],['kinetic','Space Grotesk · DM Sans'],['sora','Sora · DM Sans']].map(([id,name])=>`<option value="${id}" ${state.type===id?'selected':''}>${name}</option>`).join('')}</select><div class="style-label">MOTION PERSONALITY</div><div class="studio-segment">${[['subtle','Subtle'],['expressive','Dynamic'],['off','Off']].map(([id,label])=>`<button data-action="v4motion" data-motion="${id}" class="${state.v4Motion===id?'active':''}" aria-pressed="${state.v4Motion===id}">${label}</button>`).join('')}</div><label class="studio-toggle">Interactive 3D cards<input id="v4-tilt" type="checkbox" ${state.v4Tilt?'checked':''}></label><label class="studio-toggle">Ambient moving details<input id="v4-ambient" type="checkbox" ${state.v4Ambient?'checked':''}></label></details><div class="studio-save"><span>Browser-only preferences · Prototype</span><button data-action="v5reset">Reset</button></div>${v4PrefersReduced.matches?'<p class="studio-sub">Reduced-motion preference is enabled on your device.</p>':''}</div>`:''}</div>`};
/* Focused classroom improvements: no third-party transcript or fabricated synced captions. */
function v5PinsForLesson(){return Array.isArray(state.v5Pins[state.lesson])?state.v5Pins[state.lesson]:[]}
function v5BookmarksMarkup(){const pins=v5PinsForLesson();return `<h3>Your saved moments</h3><p>Save a moment from the playing video. Jump back to it whenever you need.</p>${pins.length?`<div class="v5-bookmark-list">${pins.map((p,i)=>`<div class="v5-bookmark"><div class="v5-bookmark-label"><button class="v5-jump" data-action="v5jump" data-seconds="${Number(p.seconds)||0}">${v5FormatTime(Number(p.seconds)||0)} ↗</button><small>${escapeHtml(p.label||'Saved study moment')}</small></div><button class="v5-delete" data-action="v5delete" data-index="${i}" aria-label="Remove bookmark ${i+1}">Remove</button></div>`).join('')}</div>`:'<div class="v5-study-hint">No bookmarks yet. Play the video and select “Save moment” to create your first one.</div>'}`}
const v5OldTabContent=tabContent;
tabContent=function(){if(state.tab==='bookmarks')return v5BookmarksMarkup();if(state.tab==='notes')return `<div class="v5-notes-heading"><h3>Your private notes</h3><button class="v5-control" data-action="v5bookmark">◷ Save current video time</button></div><p>Write while you watch. Notes and bookmarks stay locally in this browser; they are not synced to an account.</p><textarea id="lesson-notes" class="notes-input" placeholder="Your questions, reflections, and useful ideas...">${escapeHtml(state.notes[state.lesson]||'')}</textarea><div class="v5-note-actions"><span>Autosaved as you type · Lesson ${state.lesson+1}</span><button data-action="v5NotesToPins" class="v5-control">See saved moments (${v5PinsForLesson().length}) →</button></div>`;
 const rest=v5OldTabContent();return state.tab==='overview'?rest+`<div class="v5-study-hint"><strong>Simple study rhythm:</strong> watch → reflect → write a note → practise. Stay with the lesson, not the leaderboard.</div><div class="v5-lesson-checklist"><div><b>01 · Notice</b>Identify one useful idea from the video.</div><div><b>02 · Apply</b>Try the principle in a small real-world project.</div></div>`:rest;};
const v5OldClassroom=classroomPage;
classroomPage=function(){let html=v5OldClassroom();html=html.replace('<main class="classroom">',`<main class="classroom ${state.v5Focus?'v5-is-focused':''}">`);
 html=html.replace('<video controls playsinline',`<video id="v5-video" data-lesson="${state.lesson}" controls playsinline`);
 html=html.replace('</video></div><div class="class-heading">',`</video></div><div class="v5-player-toolbar"><div class="v5-player-actions"><button class="v5-control ${state.v5Focus?'active':''}" data-action="v5focus" aria-pressed="${state.v5Focus}">▣ ${state.v5Focus?'Exit focus':'Focus mode'}</button><button class="v5-control" data-action="v5bookmark">◷ Save moment</button></div><label class="v5-speed">Playback speed <select id="v5-speed" aria-label="Playback speed">${[.75,1,1.25,1.5,2].map(n=>`<option value="${n}" ${state.v5Speed==n?'selected':''}>${n}×</option>`).join('')}</select></label></div><div class="class-heading">`);
 html=html.replace('</div><div class="lesson-text">',`<button role="tab" aria-selected="${state.tab==='bookmarks'}" class="${state.tab==='bookmarks'?'active':''}" data-action="tab" data-tab="bookmarks">Bookmarks (${v5PinsForLesson().length})</button></div><div class="lesson-text">`);
 return html;};
let v5LastPersist=0;
function v5SavePosition(){const video=$('#v5-video');if(video&&Number.isFinite(video.currentTime)){state.v5Positions[Number(video.dataset.lesson||0)]=video.currentTime;storage.set('v5Positions',state.v5Positions)}}
function v5WireClassroom(){const video=$('#v5-video');if(!video)return;const previous=Number(state.v5Positions[state.lesson]||0);
 const restore=()=>{if(previous>1&&Number.isFinite(video.duration)&&previous<video.duration-1){video.currentTime=previous}video.playbackRate=Number(state.v5Speed)||1};
 video.addEventListener('loadedmetadata',restore,{once:true});if(video.readyState>=1)restore();
 video.addEventListener('timeupdate',()=>{if(Date.now()-v5LastPersist>2000){v5LastPersist=Date.now();v5SavePosition()}});
 video.addEventListener('pause',v5SavePosition);}
const v5OldRender=render;
render=function(){v5SavePosition();v5OldRender();v5WireClassroom();};
function v5RefreshStudyTab(){const box=$('.lesson-text');if(box)box.innerHTML=tabContent();$$('.class-tabs [data-action="tab"]').forEach(b=>{const selected=b.dataset.tab===state.tab;b.classList.toggle('active',selected);b.setAttribute('aria-selected',String(selected));if(b.dataset.tab==='bookmarks')b.textContent=`Bookmarks (${v5PinsForLesson().length})`})}
function v5Bookmark(){const video=$('#v5-video');if(!video){notify('Open a lesson to save video moments.');return}const time=Number(video.currentTime)||0;const notes=state.notes[state.lesson]||'';const label=notes.trim().slice(0,90)||'Saved study moment';const list=v5PinsForLesson();list.push({seconds:Math.round(time*10)/10,label});state.v5Pins[state.lesson]=list.slice(-50);v5Persist();notify(`Moment saved at ${v5FormatTime(time)}`);if(state.tab==='bookmarks')v5RefreshStudyTab()}
function v5ChangeMode(next){if(!['light','dark','system'].includes(next))return;state.v5Mode=next;v5Persist();setStyle();notify(`Appearance: ${next==='system'?'follow device':next}`)}
const v5OldHandle=handleAction;
handleAction=function(t){const a=t.dataset.action;
 if(a==='v5mode'){v5ChangeMode(t.dataset.mode);return}
 if(a==='v5custom'){state.theme='custom';v5Persist();setStyle();return}
 if(a==='v5focus'){state.v5Focus=!state.v5Focus;v5Persist();const main=$('.classroom');main?.classList.toggle('v5-is-focused',state.v5Focus);t.classList.toggle('active',state.v5Focus);t.setAttribute('aria-pressed',String(state.v5Focus));t.textContent=state.v5Focus?'▣ Exit focus':'▣ Focus mode';return}
 if(a==='v5bookmark'){v5Bookmark();return}
 if(a==='v5NotesToPins'){state.tab='bookmarks';v5RefreshStudyTab();return}
 if(a==='v5delete'){const pins=v5PinsForLesson();pins.splice(Number(t.dataset.index),1);state.v5Pins[state.lesson]=pins;v5Persist();v5RefreshStudyTab();notify('Bookmark removed.');return}
 if(a==='v5jump'){const vid=$('#v5-video');if(vid){vid.currentTime=Math.min(Number(t.dataset.seconds)||0,Math.max(0,(vid.duration||1e6)-.1));vid.scrollIntoView({behavior:'smooth',block:'center'});notify('Jumped to saved moment.')}return}
 if(a==='v5FixContrast'){const dark=v5Resolved()==='dark',obj=dark?state.v5CustomDark:state.v4Custom;obj.ink=v5Contrast(obj.background,'#ffffff')>=v5Contrast(obj.background,'#161d21')?'#ffffff':'#161d21';state.theme='custom';v5Persist();setStyle();return}
 if(a==='v5reset'){state.theme='atelier';state.type='editorial';state.v5Mode='system';state.v5CustomDark={background:'#151e24',accent:'#80c5d4',ink:'#f0f7fa'};state.v4Custom={background:'#f6f5f0',accent:'#2e7b88',ink:'#25363f'};state.v4Motion='expressive';state.v4Tilt=true;state.v4Ambient=true;state.v5Advanced=false;v5Persist();v4AmbientStop();setStyle();v4AmbientStart();notify('Theme preferences restored.');return}
 if(a==='tab'){state.tab=t.dataset.tab;v5RefreshStudyTab();return}
 if(a==='lesson'){v5SavePosition();v5OldHandle(t);return}
 v5OldHandle(t);
};
document.addEventListener('change',e=>{if(e.target.id==='v5-speed'){state.v5Speed=Number(e.target.value);let v=$('#v5-video');if(v)v.playbackRate=state.v5Speed;v5Persist()}});
document.addEventListener('input',e=>{let field=e.target.dataset.v5color;if(!field)return;const obj=v5Resolved()==='dark'?state.v5CustomDark:state.v4Custom;obj[field]=e.target.value;state.theme='custom';v5Persist();v4Apply();let indicator=$('.v5-contrast');if(indicator){const d=document.createElement('div');d.innerHTML=v5ContrastHint();indicator.replaceWith(d.firstElementChild)}$$('.palette-choice').forEach(b=>b.classList.remove('selected'))});
document.addEventListener('change',e=>{if(e.target.dataset.v5color)setStyle()});
document.addEventListener('toggle',e=>{if(e.target.id==='v5-advanced'){state.v5Advanced=e.target.open;storage.set('v5Advanced',state.v5Advanced)}},true);
v5SystemDark.addEventListener?.('change',()=>{if(state.v5Mode==='system'){v4Apply();if(state.styleOpen)$('#style-area').innerHTML=styleSwitcher()}});
document.addEventListener('keydown',e=>{if(activeRoute()!=='classroom'||e.altKey||e.ctrlKey||e.metaKey||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key.toLowerCase()==='n'){state.tab='notes';v5RefreshStudyTab()}if(e.key.toLowerCase()==='b')v5Bookmark()});


