const v6PriorHandle=handleAction;
handleAction=function(t){const a=t.dataset.action;
 if(a==='v6path'){state.v6SelectedPath=Math.max(0,Math.min(3,Number(t.dataset.index)||0));storage.set('v6SelectedPath',state.v6SelectedPath);$$('.v6-path-item').forEach(el=>{const yes=Number(el.dataset.index)===state.v6SelectedPath;el.classList.toggle('selected',yes);el.setAttribute('aria-pressed',String(yes))});const d=$('#v6-path-detail');if(d)d.innerHTML=v6SelectedMapCard();return;}
 if(a==='v6openlesson'){state.lesson=Math.max(0,Math.min(3,Number(t.dataset.index)||0));state.tab='overview';persist();navigate('classroom');return;}
 if(a==='v6notes'){state.tab='notes';navigate('classroom');return;}
 if(a==='v6reward'){const r=rewards.find(x=>x.id===t.dataset.id);if(!r)return;if(state.credits>=r.cost){state.modal='redeem:'+r.id;renderModal()}else navigate('wallet');return;}
 return v6PriorHandle(t)
};
