function v14PreviewEntry(){return v14PublicFrame(`<section class="v7-auth-card v14-preview-card" data-i18n-ignore><span class="v14-eyebrow">${v14t('EXPLORE RAWNAK','اكتشف رونق')}</span><h1>${v14t('Your next chapter starts here.','فصلك الجاي بيبدأ هنا')}</h1><p>${v14t('Explore the Academy before launch. No account or password is needed.','استكشف الأكاديمية قبل الإطلاق من غير حساب أو كلمة مرور')}</p><div class="v14-notice"><strong>${v14t('Preview access','دخول للمعاينة')}</strong><p>${v14t('These workspaces run on this device. Choosing a role does not create an account, verify an identity or grant access to a real academy.','مساحات العمل دي بتشتغل على جهازك واختيار الدور مش بينشئ حساب أو بيأكد الهوية أو بيديك صلاحية لأكاديمية فعلية')}</p></div><div class="v14-role-choices">${[['student','✳','Student workspace','مساحة الطالب'],['instructor','↗','Educator studio','استوديو المدرس'],['owner','◈','Management preview','معاينة الإدارة']].map(([role,mark,en,ar])=>`<button type="button" class="btn ${role==='student'?'primary':'outline'}" data-action="v7Demo" data-role="${role}"><span aria-hidden="true">${mark}</span> ${v14t(en,ar)} <span aria-hidden="true">↗</span></button>`).join('')}</div><p class="v14-local-note">${v14t('Your existing local drafts stay on this browser. Live registration and enrollment will open after launch.','المسودات المحلية الموجودة بتفضل محفوظة في المتصفح والتسجيل والاشتراك الفعلي هيتفتحوا بعد الإطلاق')}</p><a class="v14-inline-link" href="#/platform">${v14t('See what is available now','اعرف المتاح حاليًا')} ↗</a></section>`)}
function v7Signup(){return v14PreviewEntry()}
function v7Login(){return v14PreviewEntry()}
