/* V7.2 live, entirely fictional marketing demonstration */
const v72StageScenes={
 discover:{title:'Find your path.',sub:'Explore skills and discover the next step that fits you.',label:'Curated learning paths',meta:'YOUR JOURNEY, YOUR PACE',status:'Preview step 01 / 03',width:'33%'},
 learn:{title:'Make every lesson count.',sub:'A calm classroom built for watching, taking notes and keeping focus.',label:'A space made for learning',meta:'WATCH · NOTE · PRACTICE',status:'Preview step 02 / 03',width:'66%'},
 reward:{title:'Celebrate your progress.',sub:'See your learning milestones and discover ways to use Academy Credits.',label:'Milestones that matter',meta:'XP · CREDITS · REWARDS',status:'Preview step 03 / 03',width:'100%'}
};
function v72SetStage(which){const scene=v72StageScenes[which];if(!scene)return;const ids={title:'v72-stage-title',sub:'v72-stage-sub',label:'v72-stage-label',meta:'v72-stage-meta',status:'v72-stage-status'};for(const [k,id] of Object.entries(ids)){const el=document.getElementById(id);if(el)el.textContent=scene[k]}const bar=document.getElementById('v72-stage-bar');if(bar)bar.style.width=scene.width;document.querySelectorAll('[data-action="v72Preview"]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.stage===which)));}
const v72PreviousAction=handleAction;
handleAction=function(el){if(el.dataset.action==='v72Preview'){v72SetStage(el.dataset.stage);return}return v72PreviousAction(el)};
const v72PriorRender=render;
render=function(){v72PriorRender();const host=document.querySelector('.v7-public .v72-enter');if(!host)return;const items=[...document.querySelectorAll('.v7-public .v72-enter')];if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){items.forEach(el=>el.classList.add('is-visible'));return;}let obs=new IntersectionObserver((entries)=>{for(const x of entries){if(x.isIntersecting){x.target.classList.add('is-visible');obs.unobserve(x.target)}}},{threshold:.12,rootMargin:'0px 0px 20px 0px'});items.forEach(el=>obs.observe(el))};

/* V7.3 EXPERIENCE UPGRADE / layered over V7.2, retains its four workspaces. */
const v73key='rawnak_academy_v73_';
const v73get=(k,d)=>{try{const r=localStorage.getItem(v73key+k);return r===null?d:JSON.parse(r)}catch{return d}};
const v73put=(k,v)=>{try{localStorage.setItem(v73key+k,JSON.stringify(v))}catch{}};
let v73Step=1;
let v73Answers=v73get('draft',{goal:'',interest:'',level:'',time:''});
let v73Done=v73get('completed',false);
let v73Saved=v73get('saved',[]);
let v73Filters={query:'',category:'All',level:'All',format:'All',sort:'featured',savedOnly:false};
let v73OpenPreview=null;
const v73Catalog=courses.map((c,i)=>({...c,format:i===2?'Hybrid':i===4?'Live':'Recorded',symbol:['Aa.','</>','↗','✳','AI','◉'][i],outcome:[
  'Build a complete interface concept with clear typography and layouts.',
  'Create and publish a responsive frontend project.',
  'Turn a business idea into a clear, testable launch plan.',
  'Produce an intentional motion sequence for a digital interface.',
  'Design a practical AI workflow and review its results.',
  'Create a small photographic storytelling project.'
][i]}));
const v73One=id=>v73Catalog.find(c=>c.id===id)||null;
const v73FormatLine=c=>c.format==='Live'?'Live sessions planned · no dates announced':c.format==='Hybrid'?'Recorded lessons + planned live sessions':'Self-paced recorded lessons';
const v73SavedHas=id=>v73Saved.includes(id);
function v73Card(c){return `<article class="v73-course"><div class="v73-art"><span class="v73-art-symbol">${v7safe(c.symbol)}</span><span class="v73-art-num">COURSE ${String(v73Catalog.indexOf(c)+1).padStart(2,'0')}</span></div><div class="v73-course-body"><div class="v73-course-tags"><span>${v7safe(c.category)}</span><span>${v7safe(c.format)}</span><span>${v7safe(c.level)}</span></div><h3>${v7safe(c.title)}</h3><p>${v7safe(c.sub)}</p><div class="v73-course-facts"><span>◷ ${v7safe(c.duration)}</span><span>◫ ${c.count} lessons*</span></div></div><div class="v73-course-foot"><button class="btn sm primary" data-nav="course/${c.id}">View course ↗</button><button class="btn sm outline v73-wishlist" data-action="v73Save" data-id="${c.id}" aria-pressed="${v73SavedHas(c.id)}" title="Save course for later">${v73SavedHas(c.id)?'♥ Saved':'♡ Save'}</button></div></article>`}
function v73Filtered(){let arr=v73Catalog.filter(c=>{let q=v73Filters.query.toLowerCase().trim();return(!v73Filters.savedOnly||v73SavedHas(c.id))&&(!q||`${c.title} ${c.sub} ${c.category} ${c.outcome}`.toLowerCase().includes(q))&&(v73Filters.category==='All'||v73Filters.category===c.category)&&(v73Filters.level==='All'||c.level===v73Filters.level||c.level==='All levels')&&(v73Filters.format==='All'||c.format===v73Filters.format)});if(v73Filters.sort==='az')arr.sort((a,b)=>a.title.localeCompare(b.title));if(v73Filters.sort==='short')arr.sort((a,b)=>parseInt(a.duration)-parseInt(b.duration));return arr}
function v73Results(){const arr=v73Filtered();return arr.length?arr.map(v73Card).join(''):`<div class="v73-zero"><h3>No matching courses.</h3><p>Try another topic or remove a filter.</p><button class="btn sm outline" data-action="v73ResetFilters">Clear filters</button></div>`}
function v73Select(id,values){return `<label>${id==='query'?'Search topics':id==='category'?'Category':id==='level'?'Level':id==='format'?'Learning format':'Sort'}${id==='query'?`<input id="v73-query" type="search" placeholder="e.g. design, business, AI" value="${v7safe(v73Filters.query)}">`:`<select id="v73-${id}" aria-label="Filter by ${id}">${values.map(v=>`<option value="${v}" ${v73Filters[id]===v?'selected':''}>${v==='All'?'All '+(id==='format'?'formats':id==='category'?'categories':'levels'):v==='az'?'A–Z':v==='short'?'Shortest first':v==='featured'?'Featured':v}</option>`).join('')}</select>`}</label>`}function v73CatalogPage(){return `<main class="v73-shell"><div class="v73-toprow"><div><span class="v73-kicker">STUDENT SPACE / COURSE DISCOVERY</span><h1 class="v73-heading">Explore what's <em>possible.</em></h1><p class="v73-intro">Discover inspiring learning paths, preview lessons for free and save what interests you. All courses below are illustrative until real instructors publish.</p></div><button class="btn sm outline" data-action="v73SavedOnly" aria-pressed="${v73Filters.savedOnly}">${v73Filters.savedOnly?"♥ Show all courses":"♡ Saved courses"} (${v73Saved.length})</button></div><div class="v73-hero-value"><div><strong>Not sure where to start?</strong><div class="v73-small">Answer four quick questions to get a recommended learning path.</div></div><button class="btn sm outline" data-nav="onboarding">Personalize my journey ↗</button></div><div class="v73-filters" aria-label="Course filters">${v73Select('query')}${v73Select('category',['All','Design','Development','Business','Technology'])}${v73Select('level',['All','Beginner','Intermediate'])}${v73Select('format',['All','Recorded','Live','Hybrid'])}<label style="grid-column:1/-1;max-width:225px">Sort results<select id="v73-sort"><option value="featured" ${v73Filters.sort==='featured'?'selected':''}>Featured</option><option value="short" ${v73Filters.sort==='short'?'selected':''}>Shortest first</option><option value="az" ${v73Filters.sort==='az'?'selected':''}>A–Z</option></select></label></div><div class="v73-catalog-meta"><strong id="v73-result-count">${v73Filtered().length} learning paths</strong><span>Format and duration are sample data · no prices or start dates announced</span></div><div class="v73-grid" id="v73-results">${v73Results()}</div><p class="v73-note">*Course lessons, content, formats and instructors are illustrative design data only. You cannot buy or enrol in these examples.</p></main>`}
function v73CoursePage(id){const c=v73One(id);if(!c)return `<main class="v73-shell"><h1>Course not found.</h1><button class="btn primary" data-nav="courses">Explore courses</button></main>`;let isLive=c.format!=='Recorded';return `<main class="v73-shell"><div class="v73-breadcrumb"><button data-nav="courses">Explore courses</button> / ${v7safe(c.category)} / Course details</div><section class="v73-course-detail-hero"><div><span class="v73-kicker">${v7safe(c.category)} · ${v7safe(c.format)} · COURSE PREVIEW</span><h1 class="v73-heading">${v7safe(c.title)}</h1><p class="v73-intro">${v7safe(c.sub)} A thoughtful place to practice ideas and make measurable progress.</p><div class="v73-toolbar"><span class="v73-outline-badge">${v7safe(c.level)}</span><span class="v73-outline-badge">${v7safe(c.duration)}*</span><span class="v73-outline-badge">${c.count} sample lessons</span></div><div class="v73-plan-link"><button class="btn primary" data-action="v73Preview" data-id="${c.id}">▶ Watch free preview</button><button class="btn outline v73-wishlist" data-action="v73Save" data-id="${c.id}" aria-pressed="${v73SavedHas(c.id)}">${v73SavedHas(c.id)?'♥ Saved for later':'♡ Save for later'}</button></div><p class="v73-note">No payment or enrollment connected. The free clip uses the demo player, not this course's actual footage.</p></div><div class="v73-detail-art" aria-hidden="true"><span>${v7safe(c.symbol)}</span></div></section><div class="v73-detail-grid"><div class="v73-panel"><h2>What you'll take away.</h2><p>${v7safe(c.outcome)}</p><h2 style="margin-top:30px">Inside the learning path.</h2><p>See how focused lessons, notes and small practical exercises fit together.</p>${lessons.map((l,i)=>`<div class="v73-lesson-row"><span class="v73-lesson-id">${String(i+1).padStart(2,'0')}</span><div><strong>${v7safe(l.title)}</strong><small>${v7safe(l.duration)} · ${i===0?'Free preview':'Lesson outline'}</small></div>${i===0?`<button class="v73-quiet" data-action="v73Preview" data-id="${c.id}">Preview ↗</button>`:''}</div>`).join('')}</div><aside><div class="v73-panel"><span class="v73-kicker">COURSE INFORMATION</span><div class="v73-plan-facts"><div class="v73-plan-fact"><span>Format</span><strong>${v7safe(c.format)}</strong></div><div class="v73-plan-fact"><span>Experience</span><strong>${v7safe(c.level)}</strong></div><div class="v73-plan-fact"><span>Instructor</span><strong>${v7safe(c.teacher)}</strong></div><div class="v73-plan-fact"><span>Price</span><strong>Not published</strong></div></div>${isLive?`<div class="v73-live">◉ <span>${v73FormatLine(c)}. Internal live-classroom infrastructure is planned for V8; there is no live meeting in this demo.</span></div>`:`<div class="v73-live">◷ <span>${v73FormatLine(c)}. You can explore the existing sample classroom player.</span></div>`}<button class="btn outline" style="width:100%;margin-top:20px" data-nav="courses">Back to catalog ↗</button></div></aside></div></main>`}
const v73Questions=[
 {key:'goal',heading:'What brings you here?',sub:'Start with the outcome you want to work toward.',options:[['Career growth','Build practical skills for work'],['A new career','Move into a new field'],['My business','Turn an idea into something real'],['Personal growth','Learn something I love']]},
 {key:'interest',heading:'What sparks your curiosity?',sub:'Choose one interest for your first learning path.',options:[['Design','Creative interfaces and visual thinking'],['Development','Build for the modern web'],['Business','Launch and grow projects'],['Technology','AI and practical digital tools']]},
 {key:'level',heading:'Where would you like to begin?',sub:'No pressure; you can change this later.',options:[['Beginner','I am just getting started'],['Intermediate','I know the basics already'],['Advanced','I am ready for deeper challenges']]},
 {key:'time',heading:'How much time feels realistic?',sub:'A gentle plan is easier to keep.',options:[['10 minutes','Small, consistent steps'],['20 minutes','A steady learning habit'],['40 minutes','Longer focused sessions'],['60 minutes','A deeper daily practice']]}
];
function v73Onboarding(){const step=v73Questions[v73Step-1],current=v73Answers[step.key],name=(v7GetProfile().name||'Learner').split(' ')[0];return `<main class="v73-shell"><div class="v73-onboard-layout"><div class="v73-breadcrumb"><button data-nav="my-learning">My Learning</button> / Personal learning plan</div><span class="v73-kicker">YOUR PERSONAL JOURNEY · ${String(v73Step).padStart(2,'0')} / 04</span><h1 class="v73-heading">A better way to <em>begin, ${v7safe(name)}.</em></h1><p class="v73-intro">Four quick questions help us create a useful starting point. This is a local demonstration, not a live recommendation engine.</p><div class="v73-steps">${[1,2,3,4].map(x=>`<span class="v73-stepbar ${x<=v73Step?'done':''}" aria-label="Step ${x}"></span>`).join('')}</div><section class="v73-panel"><h2>${v7safe(step.heading)}</h2><p>${v7safe(step.sub)}</p><div class="v73-optiongrid" role="group" aria-label="${v7safe(step.heading)}">${step.options.map(([v,d])=>`<button class="v73-option" data-action="v73Choose" data-key="${step.key}" data-value="${v7safe(v)}" aria-pressed="${current===v}"><span class="v73-option-dot">${current===v?'✓':''}</span><span><strong>${v7safe(v)}</strong><small>${v7safe(d)}</small></span></button>`).join('')}</div><div class="v73-actions"><button class="btn outline" data-action="v73Back" ${v73Step===1?'disabled':''}>← Back</button><div style="display:flex;gap:10px;align-items:center"><button class="v73-quiet" data-action="v73Skip">Skip for now</button><button class="btn primary" data-action="v73Next" ${!current?'disabled':''}>${v73Step===4?'Build my path':'Continue'} →</button></div></div></section><p class="v73-note">Your choices stay in this browser for the demo and can be changed later. The marketing site remains separate from this workspace.</p></div></main>`}
function v73Recommended(){let int=v73Answers.interest;let base=int==='Design'?['design','motion','photography']:int==='Development'?['development','ai','design']:int==='Business'?['business','development','ai']:['ai','development','business'];return base.map(v73One).filter(Boolean)}
function v73Plan(){let list=v73Recommended();let minutes=Number.parseInt(v73Answers.time)||20;let weeks=(minutes*5)/60;return `<main class="v73-shell"><div class="v73-breadcrumb"><button data-nav="my-learning">My Learning</button> / Learning plan</div><div class="v73-toprow"><div><span class="v73-kicker">STUDENT SPACE / PERSONALIZED DISCOVERY</span><h1 class="v73-heading">Your journey, <em>your rhythm.</em></h1><p class="v73-intro">Here's a starting path shaped by your answers. Real personalized recommendations and progress syncing will come with the backend.</p></div><button class="btn sm outline" data-nav="onboarding">Retake onboarding ↗</button></div><div class="v73-plan"><div class="v73-highcard"><span class="v73-meta-tag">YOUR FIRST STEP</span><h2>${list[0]?v7safe(list[0].title):'Explore a new skill.'}</h2><p>Based on your interest in ${v7safe(v73Answers.interest||'learning')}, start with this illustrative path and try its free lesson preview.</p><button class="btn primary" data-nav="course/${list[0]?.id||'design'}">Explore the first course ↗</button></div><div class="v73-panel"><h2>Your learning profile.</h2><div class="v73-plan-facts"><div class="v73-plan-fact"><span>Your goal</span><strong>${v7safe(v73Answers.goal||'Explore')}</strong></div><div class="v73-plan-fact"><span>Interest</span><strong>${v7safe(v73Answers.interest||'Open to ideas')}</strong></div><div class="v73-plan-fact"><span>Starting level</span><strong>${v7safe(v73Answers.level||'Any level')}</strong></div><div class="v73-plan-fact"><span>Study rhythm</span><strong>${v7safe(v73Answers.time||'Flexible')}</strong></div></div><p class="v73-small">Example weekly rhythm: ${minutes} minutes × 5 days = ${Math.round(weeks*10)/10} hours of learning. A suggestion, not a required schedule.</p></div></div><div class="v73-toprow" style="margin-top:43px"><div><h2 class="v73-heading" style="font-size:34px">Next, <em>explore these.</em></h2><p class="v73-small">Suggested examples, not verified course offerings.</p></div></div><div class="v73-grid">${list.map(v73Card).join('')}</div><div style="margin-top:28px" class="v73-panel"><h2>Keep your progress together.</h2><p>Your dashboard includes Continue Learning, XP, notes, Rewards and the learning roadmap.</p><button class="btn primary" data-nav="my-learning">Go to My Learning ↗</button></div></main>`}
function v73DashboardBanner(){if(!v73Done)return `<section class="v73-resume-banner"><div><span class="v73-kicker">NEW / PERSONAL LEARNING PATH</span><h3>Let's find what works for you.</h3><p class="v73-small">Choose your goal, interests and pace in four quick steps.</p></div><button class="btn primary" data-nav="onboarding">Personalize my learning ↗</button></section>`;return `<section class="v73-resume-banner"><div><span class="v73-kicker">YOUR LEARNING PROFILE</span><h3>${v7safe(v73Answers.interest||'Learning')} at your own pace.</h3><p class="v73-small">Your sample roadmap is ready · ${v73Saved.length} course${v73Saved.length===1?'':'s'} saved</p></div><button class="btn outline" data-nav="learning-plan">View my plan ↗</button></section>`}
function v73ShowPreview(id){const c=v73One(id);if(!c)return;v73OpenPreview=id;let video='';try{const sample=classroomPage();const m=sample.match(/<source\s+src="([^"]+)"\s+type="video\/mp4"/);video=m?.[1]||''}catch{};const html=`<div class="v73-modal" role="dialog" aria-modal="true" aria-labelledby="v73-preview-title" id="v73-dialog"><div class="v73-modal-card"><div class="v73-modal-head"><div><span class="v73-kicker">FREE LESSON / SAMPLE VIDEO</span><h2 id="v73-preview-title">Experience the classroom.</h2></div><button class="v73-modal-close" data-action="v73Close" aria-label="Close preview">×</button></div><p class="v73-small">Sample player for <strong>${v7safe(c.title)}</strong>. This clip is a generic interface demonstration, not an official lesson from that course.</p>${video?`<video class="v73-video" controls playsinline preload="metadata" aria-label="Free classroom video preview"><source src="${video}" type="video/mp4">Your browser does not support video.</video>`:`<div class="v73-detail-art" style="height:250px">${v7safe(c.symbol)}</div>`}<div class="v73-toolbar"><span class="v73-outline-badge">Free to preview</span><span class="v73-outline-badge">No account payment</span><span class="v73-outline-badge">Recorded sample</span></div><div class="v73-actions"><p class="v73-small">See the full sample lesson interface inside your student workspace.</p><button class="btn primary" data-action="v73CloseAndLearn">Open sample classroom ↗</button></div></div></div>`;let host=document.getElementById('v7-modal-layer');if(host)host.innerHTML=html;document.querySelector('.v73-modal-close')?.focus();document.body.style.overflow='hidden'}
function v73ClosePreview(){let root=document.getElementById('v7-modal-layer');if(root){root.querySelector('video')?.pause();root.innerHTML=''}v73OpenPreview=null;document.body.style.overflow=''}
function v73UpdateCatalog(){let list=document.getElementById('v73-results');if(!list)return;list.innerHTML=v73Results();const count=document.getElementById('v73-result-count');if(count)count.textContent=v73Filtered().length+' learning paths'}
const v73OldClassical=v7ClassicalStudent;
v7ClassicalStudent=function(route){if(!courses.length&&(route==='courses'||route==='learning-plan'||route.startsWith('course/')))return v7CleanStudentEmpty(route);if(route==='onboarding')return v73Onboarding();if(route==='learning-plan')return v73Plan();if(route==='courses')return v73CatalogPage();if(route.startsWith('course/'))return v73CoursePage(route.split('/')[1]);if(route==='my-learning'){const html=v73OldClassical(route);return html.replace('<div class="container v6-content">',`<div class="container" style="padding-top:26px">${v73DashboardBanner()}</div><div class="container v6-content">`)}return v73OldClassical(route)};
v7AllowedStudent.push('onboarding','learning-plan');
v7nav.student.splice(2,0,['learning-plan','Learning plan','book']);
const v73OldSetSession=v7SetSession;
v7SetSession=function(role,profile){if(role==='student'&&profile?.source){const old=v73get('currentEmail','');if(old!==profile.email){v73put('currentEmail',profile.email);v73Done=false;v73put('completed',false);v73Saved=[];v73put('saved',[]);v73Answers={goal:'',interest:'',level:'',time:''};v73put('draft',v73Answers);v73Step=1;state.credits=0;state.xp=0;state.weeklyXP=0;state.completed=[];state.redemptions=[];state.quizDone=false;state.courseBonus=false;state.notes={};persist()}v73OldSetSession(role,profile);if(!v73Done)navigate('onboarding');return}return v73OldSetSession(role,profile)};
const v73OldAction=handleAction;
handleAction=function(t){const a=t.dataset.action;if(a==='v73Choose'){const k=t.dataset.key,val=t.dataset.value;if(v73Questions.some(x=>x.key===k&&x.options.some(v=>v[0]===val))){v73Answers[k]=val;v73put('draft',v73Answers);render()}return}if(a==='v73Next'){if(!v73Answers[v73Questions[v73Step-1].key])return notify('Choose an option to continue.');if(v73Step<4){v73Step++;render()}else{v73Done=true;v73put('completed',true);v73put('answers',v73Answers);navigate('learning-plan');notify('Your learning path is ready — preview only.')}return}if(a==='v73Back'){v73Step=Math.max(1,v73Step-1);render();return}if(a==='v73Skip'){v73Done=true;v73put('completed',true);navigate('my-learning');return}if(a==='v73SavedOnly'){v73Filters.savedOnly=!v73Filters.savedOnly;render();return}if(a==='v73ResetFilters'){v73Filters={query:'',category:'All',level:'All',format:'All',sort:'featured',savedOnly:false};render();return}if(a==='v73Save'){const id=t.dataset.id;if(!v73One(id))return;v73Saved=v73SavedHas(id)?v73Saved.filter(x=>x!==id):[...v73Saved,id];v73put('saved',v73Saved);render();notify(v73SavedHas(id)?'Saved to your list (demo).':'Removed from saved list.');return}if(a==='v73Preview'){v73ShowPreview(t.dataset.id);return}if(a==='v73Close'){v73ClosePreview();return}if(a==='v73CloseAndLearn'){v73ClosePreview();navigate('classroom');return}return v73OldAction(t)};

// Owner and instructor panels reflect decisions already approved for V8, without fictitious revenue.
const v73OwnerDefault=v7Pages.owner;
v7Pages.owner=function(){const html=v73OwnerDefault();const box=`<section class="v73-panel" style="margin:22px 0"><div class="v73-toprow"><div><span class="v73-kicker">APPROVED / V8 PLATFORM OPERATING MODEL</span><h2 style="margin-top:10px">A clearer path to launch.</h2><p>These are approved architecture decisions, not active payment or streaming integrations.</p></div><span class="v73-meta-tag">SPECIFICATION LOCKED</span></div><div class="v73-grid"><div class="v73-announcement"><strong>Hybrid commissions</strong><p class="v73-small">Platform default percentage with instructor- and course-specific overrides. Rates are not set yet.</p></div><div class="v73-announcement"><strong>Internal live classrooms</strong><p class="v73-small">Live sessions within RAWNAK, with attendance and protected access. Not live in this prototype.</p></div><div class="v73-announcement"><strong>Monthly payouts</strong><p class="v73-small">Financial review and owner approval precede monthly instructor settlements.</p></div></div></section>`;return html.replace('</main>',box+'</main>')};
const v73InstructorEarnings=v7Pages['instructor-earnings'];
v7Pages['instructor-earnings']=function(){const html=v73InstructorEarnings();const box=`<section class="v73-panel" style="margin-top:22px"><h2>How payouts will work in V8.</h2><p>Instructor earnings will be calculated from verified sales using contract commission rules. Monthly statements will display pending, approved and paid balances. No real settlement is connected here.</p><span class="v73-meta-tag">MONTHLY · APPROVED PROCESS</span></section>`;return html.replace('</main>',box+'</main>')};

const v73OldRender=render;
render=function(){v73ClosePreview();v73OldRender()};
document.addEventListener('input',e=>{if(e.target.id==='v73-query'){v73Filters.query=e.target.value;v73UpdateCatalog()}});
document.addEventListener('change',e=>{const key=e.target.id.replace(/^v73-/,'');if(['category','level','format','sort'].includes(key)&&e.target.id.startsWith('v73-')){v73Filters[key]=e.target.value;v73UpdateCatalog()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&v73OpenPreview!==null)v73ClosePreview()});
document.addEventListener('click',e=>{if(e.target?.id==='v73-dialog')v73ClosePreview()});

if(!location.hash||['#/home','#/my-learning'].includes(location.hash)){location.hash='#/'+(v7role()?v7homeOf(v7role()):'welcome')}
