function v75Svg(value,id='qr'){const {qr,n}=v75QRMatrix(value);const quiet=4,total=n+quiet*2;let runs=[];for(let y=0;y<n;y++){let start=-1;for(let x=0;x<=n;x++){let dark=x<n&&qr.isDark(y,x);if(dark&&start<0)start=x;if(!dark&&start>=0){runs.push(`M${start+quiet} ${y+quiet}h${x-start}v1h-${x-start}z`);start=-1}}}return `<svg xmlns="http://www.w3.org/2000/svg" role="img" aria-label="QR code" viewBox="0 0 ${total} ${total}" width="300" height="300" shape-rendering="crispEdges"><rect x="0" y="0" width="${total}" height="${total}" fill="#fff"/><path fill="#111" d="${runs.join('')}"></path></svg>`}
