function v75QrDownloadPNG(id){const entry=v75FindQR(id);if(!entry)return;const {qr,n}=v75QRMatrix(v75Link(id));const quiet=4,step=12,side=(n+quiet*2)*step;const cv=document.createElement('canvas');cv.width=side;cv.height=side;const ctx=cv.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,side,side);ctx.fillStyle='#101010';for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))ctx.fillRect((x+quiet)*step,(y+quiet)*step,step,step);cv.toBlob(b=>{if(b){v75DownloadBlob(b,'rawnak-'+id+'.png');notify('High-resolution PNG downloaded.')}},'image/png')}
