function v75GuestBookLanding(route){const id=v14DecodeRoute(route.split('/').slice(1).join('/')),e=v75StaticEntry(id);return `<div class="v7-public">${v7guestHeader()}<main class="v7-form-wrap"><section class="v7-auth-card" style="max-width:790px;margin:auto"><span class="v75-eye">RAWNAK ACADEMY / PRINTED COMPANION</span><h1 style="letter-spacing:-.03em">${e?'Your book has a digital chapter.':'Open the next chapter.'}</h1>${e?`<p><strong>${v75Escape(e.book.title)}</strong> · ${v75Escape(e.chapter.label)}</p><p>Lesson ${e.chapter.lesson+1} · ${v75Escape(e.chapter.kind)} · Page ${v75Escape(e.chapter.page)}</p><p>This is a sample QR preview. Sign in to a student account to continue to the lesson. Real purchases and access controls are not enabled.</p>`:'<p>This QR is not available in this browser-only preview. Instructor-created QR drafts need a connected V8 database to resolve across devices.</p>'}<div class="v75-actions"><button class="v75-button primary" data-nav="signup">Create free account ↗</button><button class="v75-button" data-nav="login">Explore preview</button><button class="v75-button" data-nav="welcome">Academy home</button></div></section></main>${v7GuestFooter()}</div>`}
function v75StudentBookLink(route){const id=v14DecodeRoute(route.split('/').slice(1).join('/')),found=v75StaticEntry(id);if(!found)return `<main class="v7-app-main v75-page">${v75Heading('BOOK COMPANIONS','QR link not found.','Try a sample book in your library. Custom QR redirects need the V8 backend.')}<button class="v75-button primary" data-nav="book-library">Go to Book Library ↗</button></main>`;return `<main class="v7-app-main v75-page">${v75Heading('BOOK COMPANION / PAGE '+v75Escape(found.chapter.page),'Your chapter, <em>connected.</em>','This QR opens a lesson-specific study destination. The content below is an illustrative preview of the experience.')}${v75Demo}<div class="v75-panel" style="max-width:850px"><span class="v75-eye">${v75Escape(found.book.title)} · ${v75Escape(found.book.edition)}</span><h2>${v75Escape(found.chapter.label)}</h2><p>${v75Escape(lessons[found.chapter.lesson]?.description||'Lesson companion.')}</p><div class="v75-actions"><button class="v75-button primary" data-action="v75EnterChapter" data-id="${v75Escape(id)}">${found.chapter.kind==='quiz'?'Open practice quiz':found.chapter.kind==='resource'?'Open lesson files':'Open linked lesson'} ↗</button><button class="v75-button" data-nav="book-library">My Smart Books</button></div><div class="v75-fineprint">In this frontend preview, course enrollment isn't enforced. The production release will check whether the student may access the chosen lesson.</div></div></main>`}
const v75BookReadings=[];
function v75SplitStudy(){const x=v75BookReadings[v75ReaderLesson]||v75BookReadings[0];const notes=v74State.notes.filter(n=>n.lesson===v75ReaderLesson);return `<main class="v7-app-main v75-page">${v75Heading('STUDENT TOOLS / SPLIT STUDY','Watch, read, <em>connect.</em>','A quiet workspace combining a sample lesson video and a reading companion — designed for focused practice.',`<button class="v75-button" data-nav="classroom">Open Cinema Classroom ↗</button>`)}${v75Demo}<div class="v75-reader-tools"><label class="v75-label">Current lesson<select id="v75-reader-lesson" class="v75-control" style="min-width:270px">${lessons.map((l,i)=>`<option value="${i}" ${i===v75ReaderLesson?'selected':''}>${i+1}. ${v75Escape(l.title)}</option>`).join('')}</select></label><div class="v75-reader-tabs"><button class="v75-button ${v75ReaderTab==='book'?'on':''}" data-action="v75ReaderTab" data-tab="book">Book text</button><button class="v75-button ${v75ReaderTab==='notes'?'on':''}" data-action="v75ReaderTab" data-tab="notes">My notes (${notes.length})</button></div></div><div class="v75-split"><div class="v75-video"><video id="v75-split-video" controls preload="metadata" playsinline src="${v75SafeSampleVideo()}"></video><caption>Illustrative video sample · course-specific assets require the V8 content system.</caption></div><aside class="v75-reading"><span class="v75-kicker">BOOK COMPANION / LESSON ${String(v75ReaderLesson+1).padStart(2,'0')}</span>${v75ReaderTab==='notes'?`<h2>Notes for this lesson.</h2>${notes.length?notes.map(n=>`<p><strong>${v74Clock(n.time)}</strong> · ${v75Escape(n.text)}</p>`).join(''):'<p>No notes yet. Add a note below and use Cinema Classroom to review it.</p>'}<form id="v75-split-note-form" class="v75-form"><label>Your note<textarea name="text" required maxlength="1200" placeholder="Write down an idea or question"></textarea></label><button class="v75-button primary" type="submit">Save note ↗</button></form>`:`<h2>${v75Escape(x.title)}</h2><div class="v75-quote">${v75Escape(x.lead)}</div>${x.paras.map(p=>`<p>${v75Escape(p)}</p>`).join('')}<div class="v75-classroom-callout"><div><strong>Remember what matters.</strong><p>Try an active recall quiz in the full classroom.</p></div><button class="v75-button tiny" data-action="v75OpenFullLesson">Study ↗</button></div>`}</aside></div><div class="v75-fineprint">Split Study preserves the learner's notes locally. It does not grant a paid course entitlement or store any activity server-side.</div></main>`}
function v75SafeSampleVideo(){if(window.v75CachedVideo)return window.v75CachedVideo;const test=document.createElement('div');try{let sample=v74OldClassroom();let m=sample.match(/<source\s+src="([^"]+)"\s+type="video\/mp4"/);window.v75CachedVideo=m?m[1]:''}catch{window.v75CachedVideo=''}return window.v75CachedVideo}
// Route extensions: v7Valid instructor/owner allowlists have been extended in the build step.
v7AllowedStudent.push('book-library','split-study');
v7nav.student.splice(v7nav.student.findIndex(x=>x[0]==='resources')+1,0,['book-library','Smart Books','book'],['split-study','Split Study','play']);
v7nav.instructor.splice(2,0,['instructor-books','Smart Books','book'],['instructor-qr-studio','QR Print Studio','spark'],['instructor-question-bank','Question Bank','note']);
v7nav.owner.splice(v7nav.owner.findIndex(x=>x[0]==='owner-courses')+1,0,['owner-books','Book operations','book']);
v7Pages['instructor-books']=v75InstructorBooks;
v7Pages['instructor-qr-studio']=v75PrintStudio;
v7Pages['instructor-question-bank']=v75QuestionBank;
v7Pages['owner-books']=v75OwnerBooks;
const v75PreviousClassical=v7ClassicalStudent;
v7ClassicalStudent=function(route){if(route==='book-library')return v7CleanStudentEmpty(route);if(route==='split-study'&&!lessons.length)return v7CleanStudentEmpty(route);if(route==='book-library')return v75StudentBooks();if(route==='split-study')return v75SplitStudy();if(route.startsWith('book/'))return v7CleanStudentEmpty('book-library');return v75PreviousClassical(route)};
const v75OldTools=v7Pages.tools;
v7Pages.tools=function(){return v75OldTools().replace('</main>',`<section class="v75-classroom-callout"><div><span class="v75-eye">NEW / SMART STUDY TOOLS</span><strong>Printed books, meet digital lessons.</strong><p>Open a book QR or study with video and reading side by side.</p></div><div class="v75-actions"><button class="v75-button primary" data-nav="book-library">Smart Books ↗</button><button class="v75-button" data-nav="split-study">Split Study</button></div></section></main>`)};
const v75OldAction=handleAction;
handleAction=function(t){const a=t.dataset.action;const id=t.dataset.id;
 if(a==='v75SelectBook'){v75Selected=id;v75SelectedQR=v75Book(id)?.chapters[0]?.id||null;v75Save();render();return}
 if(a==='v75SelectQR'){v75SelectedQR=id;v75Save();render();return}
 if(a==='v75DownloadSVG'){v75QrDownloadSVG(id);return}
 if(a==='v75DownloadPNG'){v75QrDownloadPNG(id);return}
 if(a==='v75CopyLink'){const value=v75Link(id);(navigator.clipboard?.writeText(value)||Promise.reject()).then(()=>notify('QR link copied.')).catch(()=>notify('Copy this link: '+value));return}
 if(a==='v75PrintAll'){v75PrintAll();return}
 if(a==='v75RemoveQR'&&v7role()==='instructor'){for(const b of v75Books)b.chapters=b.chapters.filter(c=>c.id!==id);v75SelectedQR=null;v75Save();render();return}
 if(a==='v75RemoveBook'&&v7role()==='instructor'){v75Books=v75Books.filter(b=>b.id!==id);v75Selected=v75Books[0]?.id||'';v75SelectedQR=v75Books[0]?.chapters[0]?.id||null;v75Save();render();return}
 if(a==='v75RemoveQuestion'&&v7role()==='instructor'){v75Questions=v75Questions.filter(q=>q.id!==id);v75Save();render();return}
 if(a==='v75ToggleQuestion'&&v7role()==='instructor'){const q=v75Questions.find(q=>q.id===id);if(q)q.published=!q.published;v75Save();render();return}
 if(a==='v75ExportQuestions'&&v7role()==='instructor'){const data=JSON.stringify({schema:'rawnak-academy-question-bank-demo-v1',questions:v75Questions},null,2);v75DownloadBlob(new Blob([data],{type:'application/json'}),'rawnak-question-bank-demo.json');notify('JSON question bank downloaded.');return}
 if(a==='v75OpenBookLink'){navigate('book/'+id);return}
 if(a==='v75EnterChapter'){const entry=v75StaticEntry(id);if(!entry)return;state.lesson=entry.chapter.lesson;state.tab=entry.chapter.kind==='quiz'?'practice':entry.chapter.kind==='resource'?'resources':'overview';persist();navigate('classroom');return}
 if(a==='v75ReaderTab'){v75ReaderTab=t.dataset.tab==='notes'?'notes':'book';render();return}
 if(a==='v75OpenFullLesson'){state.lesson=v75ReaderLesson;state.tab='overview';persist();navigate('classroom');return}
 return v75OldAction(t)
};
document.addEventListener('submit',e=>{
 if(e.target.id==='v75-book-form'){e.preventDefault();if(v7role()!=='instructor')return;const fd=new FormData(e.target);const title=String(fd.get('title')||'').trim().slice(0,85),edition=String(fd.get('edition')||'').trim().slice(0,40),description=String(fd.get('description')||'').trim().slice(0,220),course=String(fd.get('course')||'');if(title.length<3||!edition||(course!==''&&!courses.some(c=>c.id===course)))return notify('Add a title and edition.');const id=v75Id();v75Books.push({id,title,edition,description,course,chapters:[]});v75Selected=id;v75SelectedQR=null;v75Save();render();notify('Book draft created locally.');return}
 if(e.target.id==='v75-qr-form'){e.preventDefault();if(v7role()!=='instructor')return;const fd=new FormData(e.target);let b=v75Book(String(fd.get('bookId'))),lesson=Number(fd.get('lesson')),kind=String(fd.get('kind')),page=String(fd.get('page')||'').trim().slice(0,8),label=String(fd.get('label')||'').trim().slice(0,85);if(!b||!Number.isInteger(lesson)||lesson<0||lesson>=lessons.length||!['lesson','quiz','resource','preview'].includes(kind)||!label)return notify('Complete all required QR details.');const id=v75Id();b.chapters.push({id,lesson,kind,page,label,enabled:true});v75SelectedQR=id;v75Save();render();notify('Lesson QR created. Open QR Print Studio to export.');return}
 if(e.target.id==='v75-question-form'){e.preventDefault();if(v7role()!=='instructor')return;const fd=new FormData(e.target);const question=String(fd.get('question')||'').trim().slice(0,240),topic=String(fd.get('topic')||'').trim().slice(0,50),choices=['A','B','C'].map(k=>String(fd.get('choice'+k)||'').trim().slice(0,125)),correct=Number(fd.get('correct')),lesson=Number(fd.get('lesson')),course=String(fd.get('course')||''),level=String(fd.get('level')||'Easy'),explanation=String(fd.get('explanation')||'').trim().slice(0,380);if(!question||!topic||choices.some(c=>!c)||!Number.isInteger(correct)||correct<0||correct>2||!Number.isInteger(lesson)||lesson< -1||(lesson!==-1&&lesson>=lessons.length)||(course!==''&&!courses.some(c=>c.id===course)))return notify('Please complete the question and three answers.');v75Questions.push({id:v75Id(),question,topic,choices,correct,lesson,course,level,explanation,published:false});v75Save();render();notify('Question saved as local draft.');return}
 if(e.target.id==='v75-book-link-form'){e.preventDefault();let link=String(new FormData(e.target).get('link')||'').trim();let id='';if(link.includes('#/book/'))id=link.split('#/book/')[1].split(/[?&]/)[0];else if(/^[a-zA-Z0-9-]{3,90}$/.test(link))id=link;try{id=decodeURIComponent(id)}catch{}if(!id||!v75StaticEntry(id))return notify('This QR is not available in the current preview.');navigate('book/'+id);return}
 if(e.target.id==='v75-split-note-form'){e.preventDefault();if(v7role()!=='student')return;let text=String(new FormData(e.target).get('text')||'').trim().slice(0,1200);if(!text)return;const sec=Math.round(document.getElementById('v75-split-video')?.currentTime||0);v74State.notes.push({id:v75Id(),lesson:v75ReaderLesson,time:sec,text});v74Save();v75ReaderTab='notes';render();notify('Study note saved on this device.');return}
});
document.addEventListener('input',e=>{if(e.target.id==='v75-question-search'){v75QuestionFilter=e.target.value;const node=e.target;let sel=node.selectionStart;let parent=node.closest('.v75-panel');if(parent){const list=v75Questions.filter(q=>`${q.question} ${q.topic} ${q.level}`.toLowerCase().includes(v75QuestionFilter.toLowerCase()));parent.querySelectorAll('.v75-question-item').forEach(x=>x.remove());const host=document.createElement('div');host.innerHTML=list.map(v75QuestionCard).join('');parent.append(...host.children);const badge=parent.querySelector('.v75-chip');if(badge)badge.textContent=list.length+' FOUND';}}});
document.addEventListener('change',e=>{if(e.target.id==='v75-reader-lesson'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=0&&n<lessons.length){v75ReaderLesson=n;render()}}});
const v75PrevRender=render;
render=function(){v75PrevRender();if(v7role()==='student'&&activeRoute()==='my-learning'&&v75Books.length){const host=document.querySelector('.v7-workarea .v7-app-main');if(host){host.insertAdjacentHTML('beforeend',`<section class="v75-classroom-callout" style="margin:20px 25px"><div><span class="v75-eye">NEW / SMART BOOKS</span><strong>Take your printed workbook online.</strong><p>Read chapters side by side with the lesson video.</p></div><button class="v75-button primary" data-nav="book-library">Open Smart Books ↗</button></section>`)}}};


/* RAWNAK Academy V7.6 — interactive public demo controls. No backend mutation. */
function v76Step(index){
 const stages=[
  {title:'Your next step<br>starts here.',tag:'CURATED LEARNING',course:'Explore creative skills',desc:'Find a course that fits your ambition.',metric:'01',width:26,ft:'Build real skills',fd:'One step at a time'},
  {title:'Make every lesson<br>matter.',tag:'FOCUSED CLASSROOM',course:'Design your first project',desc:'Learn, practice, make progress.',metric:'02',width:63,ft:'Stay in your flow',fd:'Notes · Practice · Video'},
  {title:'Look how far<br>you have come.',tag:'YOUR ACHIEVEMENTS',course:'Skills worth celebrating',desc:'Turn the work into confidence.',metric:'03',width:100,ft:'A milestone reached',fd:'Earn rewards as you grow'}
 ]; const s=stages[((index%stages.length)+stages.length)%stages.length];
 const updates={'v76-device-title':s.title,'v76-device-tag':s.tag,'v76-device-course':s.course,'v76-device-desc':s.desc,'v76-device-metric':s.metric,'v76-float-title':s.ft,'v76-float-desc':s.fd};
 for(const [id,val] of Object.entries(updates)){let n=document.getElementById(id);if(n)n.innerHTML=val}
 let bar=document.getElementById('v76-device-progress');if(bar)bar.style.width=s.width+'%';
 document.querySelectorAll('[data-v76-step]').forEach((el,i)=>{el.classList.toggle('is-active',i===index);el.setAttribute('aria-pressed',String(i===index))});
 window.__v76CurrentStep=index;
}
function v76Story(index){
 const rows=[
  ['YOUR LEARNING SPACE','A clear start.<br>Made for you.','Personal recommendations based on your goals.'],
  ['FOCUS CLASSROOM','A calmer way<br>to keep going.','Video, notes and practice in one thoughtful place.'],
  ['YOUR PROGRESS','Every small step<br>adds up.','Visible milestones and meaningful rewards.']
 ];index=((index%3)+3)%3;
 const ids=['v76-story-kicker','v76-story-head','v76-story-description'];
 ids.forEach((id,i)=>{let el=document.getElementById(id);if(el)el.innerHTML=rows[index][i]});
 let meter=document.getElementById('v76-story-count');if(meter)meter.textContent=String(index+1).padStart(2,'0')+' / 03';
 let bar=document.getElementById('v76-story-bar');if(bar)bar.style.width=((index+1)*33.333)+'%';
 document.querySelectorAll('[data-v76-story]').forEach((el,i)=>el.classList.toggle('is-active',i===index));
 window.__v76CurrentStory=index;
}
function v76Init(){
 const root=document.querySelector('.v76-public'); if(!root)return;
 v76Step(0);v76Story(0);
 const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const visible=Array.from(root.querySelectorAll('.v76-reveal'));
 if(!reduced&&'IntersectionObserver'in window){
  const obs=new IntersectionObserver(entries=>{for(const ent of entries)if(ent.isIntersecting){ent.target.classList.add('v76-visible');obs.unobserve(ent.target)}},{threshold:.08,rootMargin:'0px 0px 20px 0px'});
  visible.forEach(el=>obs.observe(el));
  root.classList.add('v76-ready');
 }else visible.forEach(el=>el.classList.add('v76-visible'));
 if(window.__v76HeroTimer)clearInterval(window.__v76HeroTimer);
 if(!reduced){window.__v76HeroTimer=setInterval(()=>{
  if(!document.querySelector('.v76-public')||document.hidden)return;
  if(Date.now()-(window.__v76ManualAt||0)<14000)return;
  const hero=document.querySelector('.v76-hero');if(hero&&hero.getBoundingClientRect().bottom>0)v76Step(((window.__v76CurrentStep||0)+1)%3);
 },5100)}
}
document.addEventListener('click',e=>{
 let t=e.target.closest('[data-v76-step]');if(t){const n=Number(t.dataset.v76Step);window.__v76ManualAt=Date.now();v76Step(n);return}
 t=e.target.closest('[data-v76-story]');if(t){v76Story(Number(t.dataset.v76Story));return}
 t=e.target.closest('[data-v76-story-next]');if(t){v76Story((window.__v76CurrentStory||0)+1);return}
 t=e.target.closest('[data-v76-story-prev]');if(t){v76Story((window.__v76CurrentStory||0)-1);return}
 t=e.target.closest('[data-v76-gift]');if(t){
  const messages={believe:'I believe in everything you\'re becoming.',proud:'You worked so hard. I\'m so proud of you.',just:'A small reminder that you matter.'};
  const m=document.getElementById('v76-gift-message');if(m)m.textContent=messages[t.dataset.v76Gift]||messages.believe;
  document.querySelectorAll('[data-v76-gift]').forEach(b=>{let a=b===t;b.classList.toggle('is-active',a);b.setAttribute('aria-pressed',String(a))});return;
 }
 t=e.target.closest('[data-v76-qr-demo]');if(t){const s=document.getElementById('v76-books-scene');if(!s)return;s.classList.toggle('is-scanned');t.innerHTML=s.classList.contains('is-scanned')?'Close chapter preview <span>↗</span>':'Try the QR experience <span>↗</span>';t.setAttribute('aria-expanded',String(s.classList.contains('is-scanned')))}
});
document.addEventListener('pointermove',e=>{
 if(e.pointerType==='touch'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const z=e.target.closest('.v76-tilt-zone');if(!z)return;
 let d=document.getElementById('v76-device');if(!d)return;
 const box=z.getBoundingClientRect(), x=(e.clientX-box.left)/box.width-.5,y=(e.clientY-box.top)/box.height-.5;
 d.style.transform=`rotate(${(-6+x*4).toFixed(2)}deg) rotateY(${(-7+x*8).toFixed(2)}deg) rotateX(${(-y*6).toFixed(2)}deg)`;
});
document.addEventListener('pointerout',e=>{if(e.target.closest('.v76-tilt-zone')&&!e.relatedTarget?.closest?.('.v76-tilt-zone')){const d=document.getElementById('v76-device');if(d)d.style.transform=''}});

